// Question banks extracted from the accompanying PDF source files.
const PROTID=[["Đặc điểm cấu tạo chung nào sau đây đúng với tất cả các acid amin cơ bản trong phân tử protein (ngoại trừ prolin)?",["Nhóm -NH2 và -COOH cùng gắn vào nguyên tử carbon alpha (Cα)","Nhóm -NH2 và -COOH gắn vào hai nguyên tử carbon khác nhau","Luôn chứa 2 nhóm carboxyl và 1 nhóm amin","Luôn chứa nhóm imin (-NH-) trong vòng pyrrolidin"],0,"Giải thích: Các acid amin cơ bản trong protein (trừ prolin là acid imin) đều có ít nhất 1 nhóm -COOH và 1 nhóm -NH2 tự do cùng gắn vào nguyên tử Cα."],["Acid amin nào sau đây KHÔNG phải là acid amin cơ bản (không được mã hóa trực tiếp bởi bộ ba di truyền) nhưng được xếp là acid amin thứ 21 trong một số enzyme?",["4-hydroxyprolin","Selenocystein","Ornithin","Citrullin"],1,"Giải thích: Selenocystein là acid amin thứ 21 có trong enzym glutathione peroxidase, formate dehydrogenase..., khác cystein ở chỗ nguyên tử S được thay bằng Se, không được mã hóa trực tiếp bởi bộ 3 nu tiêu chuẩn mà được chèn vào protein sau dịch mã."],["Sản phẩm thủy phân hydroxy hóa của Prolin và Lysin (4-hydroxyprolin và 5-hydroxylysin) là thành phần cấu tạo đặc trưng của loại protein nào?",["Albumin huyết thanh","Hemoglobin","Collagen","Keratin"],2,"Giải thích: 4-hydroxyprolin và 5-hydroxylysin là các dẫn xuất acid amin ít gặp có trong thành phần của collagen và một số protein thực vật."],["Acid amin nào sau đây có chứa nhóm R là chuỗi hydrocarbon mang nhóm Hydroxyl (-OH)?",["Serin và Threonin","Cysteine và Methionine","Leucine và Isoleucine","Asparagine và Glutamine"],0,"Giải thích: Serin (Ser) và Threonin (Thr) là hai acid amin trung tính có nhóm R chứa nhóm hydroxyl (-OH)."],["Acid amin nào chứa lưu huỳnh (S) trong nhóm R?",["Phe và Tyr","Cys và Met","Lys và Arg","Asp và Glu"],1,"Giải thích: Cystein (Cys - chứa nhóm -SH sulfhydryl) và Methionin (Met - chứa nhóm thioester) là 2 acid amin chứa lưu huỳnh."],["Acid amin nào thuộc nhóm acid amin kiềm (acid diamino monocarboxylic)?",["Aspartat và Glutamat","Lysin và Arginin","Phenylalanin và Tyrosin","Valin và Leucin"],1,"Giải thích: Lysin (chứa nhóm epsilon-amino) và Arginin (chứa nhóm guanidium) là các acid amin kiềm có chứa 2 nhóm amin và 1 nhóm carboxyl."],["Gốc R của Histidin có chứa nhân dị vòng đặc trưng nào?",["Nhân Indol","Nhân Imidazol","Nhân Pyrrolidin","Nhân Benzen"],1,"Giải thích: Histidin (His) có gốc R chứa nhân dị vòng Imidazol, có pKa ~ 6.0-6.8 nên đóng vai trò đệm pH quan trọng ở pH sinh lý."],["Gốc R của Tryptophan có chứa nhân dị vòng nào?",["Nhân Imidazol","Nhân Indol","Nhân Phenol","Nhân Guanidium"],1,"Giải thích: Tryptophan (Trp) có gốc R chứa nhân Indol, hấp thụ tia UV mạnh nhất ở bước sóng 280 nm."],["Danh sách nào sau đây gồm toàn các acid amin thiết yếu (cơ thể người không tự tổng hợp được, phải lấy từ thức ăn)?",["Alanin, Glycin, Serin, Prolin","Valin, Leucin, Isoleucin, Methionin, Phenylalanin, Threonin, Tryptophan, Lysin","Acid aspartic, Acid glutamic, Glutamin, Asparagin","Tyrosin, Cysteine, Glycin, Alanin"],1,"Giải thích: 8 acid amin thiết yếu bắt buộc ở người trưởng thành là Val, Leu, Ile, Met, Phe, Thr, Trp, Lys (cùng His và Arg ở trẻ em)."],["Acid amin nào duy nhất trong 20 acid amin cơ bản KHÔNG có tính quang hoạt (không có carbon bất đối Cα)?",["Alanin","Glycin","Prolin","Serin"],1,"Giải thích: Glycin (Gly) có gốc R là -H, do đó nguyên tử Cα nối với 2 nguyên tử H nên không có trung tâm bất đối, không có tính quang hoạt."],["Các acid amin nhân thơm (Tyrosin, Tryptophan, Phenylalanin) có khả năng hấp thụ ánh sáng tử ngoại (UV) mạnh nhất ở dải bước sóng nào?",["190 - 210 nm","240 - 280 nm (đặc biệt là 280 nm)","340 - 380 nm","540 - 570 nm"],1,"Giải thích: Các aa có nhân thơm (Trp, Tyr, Phe) hấp thụ tử ngoại mạnh ở 240 - 280 nm. Do đó, bước sóng 280 nm thường được ứng dụng để định lượng protein."],["Trạng thái ion nào của acid amin chiếm tỷ lệ cao nhất khi môi trường có pH bằng đúng pHi (pH đẳng điện)?",["Cation tích điện dương (+)","Anion tích điện âm (-)","Ion lưỡng cực (Zwitterion) có tổng điện tích bằng 0","Dạng phân tử trung hòa không phân ly"],2,"Giải thích: Ở pH = pHi (pH đẳng điện), acid amin tồn tại chủ yếu dưới dạng ion lưỡng cực (zwitterion), tổng điện tích bằng 0, không di chuyển trong điện trường."],["Khi đặt một acid amin vào dung dịch đệm có pH < pHi (môi trường acid hơn pHi), acid amin đó sẽ tích điện gì và di chuyển về cực nào trong điện trường?",["Tích điện âm (-), di chuyển về Anode (+)","Tích điện dương (+), di chuyển về Cathode (-)","Không tích điện, đứng yên tại chỗ","Tích điện âm (-), di chuyển về Cathode (-)"],1,"Giải thích: Khi pH mt < pHi, acid amin nhận H+ trở thành Cation tích điện dương (+), do đó di chuyển về cực âm (Cathode/-) trong điện trường. Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Khi pH môi trường > pHi (môi trường kiềm hơn pHi), acid amin sẽ phân ly H+ để tồn tại ở dạng nào và di chuyển về cực nào?",["Anion tích điện âm (-), di chuyển về cực dương (Anode/+)","Cation tích điện dương (+), di chuyển về cực âm (Cathode/-)","Ion lưỡng cực, không di chuyển","Anion tích điện âm (-), di chuyển về cực âm (Cathode/-)"],0,"Giải thích: Khi pH mt > pHi, acid amin nhường H+ trở thành Anion tích điện âm (-), nên di chuyển về cực dương (Anode/+) trong điện trường."],["Phản ứng của acid amin với thuốc thử Ninhydrin đun nóng tạo ra phức chất có màu gì đặc trưng dùng để phát hiện và định lượng?",["Màu vàng chanh","Màu xanh lá cây","Màu đỏ tía / tím (purple, λmax = 570 nm)","Màu đen tuyền"],2,"Giải thích: Phản ứng Ninhydrin tạo phức chất màu đỏ tía / tím (purple) có hấp thụ cực đại ở 570 nm (riêng prolin tạo màu vàng), dùng hiện màu sắc ký/điện di."],["Thuốc thử Sanger (2,4-dinitrofluorobenzen - DNFB) phản ứng với nhóm nhóm nào của acid amin/peptid để ứng dụng xác định acid amin đầu N-tận?",["Nhóm alpha-carboxyl (-COOH)","Nhóm alpha-amin (-NH2) tự do ở đầu N-tận","Nhóm sulfhydryl (-SH) của Cysteine","Nhóm guanidium của Arginine"],1,"Giải thích: DNFB (thuốc thử Sanger) gắn vào nhóm alpha-amin tự do ở đầu N-tận trong môi trường kiềm yếu tạo dinitrophenyl-peptid (DNP-peptid)."],["Phương pháp thoái hóa Edman sử dụng hóa chất Phenylisothiocyanat (PITC) có ưu điểm nổi bật nào so với phản ứng Sanger trong xác định trình tự chuỗi polypeptide?",["Cắt đứt toàn bộ chuỗi peptid thành các aa tự do cùng lúc","Tách lần lượt từng acid amin đầu N-tận mà không làm thủy phân phần còn lại của chuỗi peptid, cho phép tự động hóa","Chỉ phản ứng với acid amin đầu C-tận","Không cần dùng sắc ký để định danh"],1,"Giải thích: Phản ứng Edman tách chọn lọc từng gốc aa đầu N-tận dưới dạng dẫn xuất PTH-aa mà không phá hủy phần chuỗi peptid còn lại, giúp xác định nối tiếp từ aa 1, 2, 3... và đã được tự động hóa."],["Phản ứng Sorensen (cho acid amin tác dụng với Aldehyd/Formol) nhằm mục đích gì?",["Khóa nhóm alpha-amin (-NH2) để định lượng nhóm -COOH bằng phương pháp chuẩn độ NaOH","Khóa nhóm -COOH để chuẩn độ nhóm -NH2","Tạo phức màu đỏ tím với Cu2+","Khử nhóm carboxyl tạo alcol"],0,"Giải thích: Phản ứng Sorensen dùng formol khóa nhóm alpha-amin thành methylene amino acid, làm mất tính kiềm giúp chuẩn độ trực tiếp nhóm -COOH bằng NaOH."],["Phản ứng Van-Slyke cho acid amin tác dụng với acid nitrơ (HNO2) giải phóng khí gì để định lượng acid amin?",["Khí CO2","Khí N2","Khí NH3","Khí H2S"],1,"Giải thích: Phản ứng Van-Slyke: alpha-amin + HNO2 -> giải phóng N2 (đo thể tích N2 tạo thành để tính hàm lượng aa có nhóm amin bậc 1)."],["Enzyme Decarboxylase xúc tác cho phản ứng khử nhóm alpha-carboxyl của acid amin tạo amin sinh học tương ứng cần coenzyme nào?",["NAD+","Pyridoxal phosphate (PLP / Vitamin B6)","Thiamin pyrophosphate (TPP)","FAD"],1,"Giải thích: Enzyme Decarboxylase khử carboxyl của aa tạo amin có hoạt tính sinh học có coenzyme bắt buộc là Pyridoxal phosphate (Vitamin B6)."],["Phản ứng Xanthoproteic (tác dụng với HNO3 đậm đặc tạo màu vàng) dùng để nhận biết các acid amin có chứa nhóm chức nào?",["Nhóm Thiol (-SH)","Nhân Benzen / Nhân thơm (Tyr, Phe, Trp)","Nhóm Guanidium","Nhóm Imidazol"],1,"Giải thích: Phản ứng Xanthoproteic nitrơ hóa nhân thơm (Trp, Tyr, Phe) bằng HNO3 đặc cho sản phẩm màu vàng (chuyển sang da cam trong môi trường kiềm)."],["Phản ứng Sakaguchi cho màu đỏ sẫm đặc trưng với nhóm Guanidine có trong acid amin nào?",["Lysin","Arginin","Histidin","Tryptophan"],1,"Giải thích: Phản ứng Sakaguchi (+ alpha-naphthol và hypobromite kiềm) đặc hiệu cho nhóm Guanidine của Arginin."],["Liên kết peptid được hình thành do sự ngưng tụ giữa hai nhóm chức nào của 2 acid amin và giải phóng 1 phân tử nước?",["Nhóm alpha-carboxyl của aa 1 và nhóm alpha-amin của aa 2","Nhóm -SH của Cys 1 và -SH của Cys 2","Hai nhóm alpha-carboxyl của 2 aa","Gốc R của aa 1 và gốc R của aa 2"],0,"Giải thích: Liên kết peptid (bản chất là liên kết amid) hình thành giữa nhóm alpha-carboxyl của aa này và nhóm alpha-amin của aa kế tiếp."],["Phản ứng Biuret phản ứng với Cu2+ trong môi trường kiềm tạo phức chất màu tím hồng yêu cầu peptide/protein phải có ít nhất bao nhiêu liên kết peptid (hoặc bao nhiêu gốc aa)?",["Ít nhất 1 liên kết peptid (dipeptide)","Ít nhất 2 liên kết peptid (từ 3 gốc acid amin trở lên)","Ít nhất 10 liên kết peptid","Phải là protein trọng lượng phân tử > 100.000 Da"],1,"Giải thích: Phản ứng Biuret yêu cầu phân tử phải chứa từ 2 liên kết peptid trở lên (tức tripeptide / 3 gốc aa trở lên) mới tạo phức màu tím với Cu2+/OH-."],["Glutathion là một tripeptide có hoạt tính chống oxy hóa quan trọng trong cơ thể, được cấu tạo từ 3 acid amin nào?",["Glu - Cys - Gly (gamma-glutamyl-cysteinyl-glycin)","Ala - Cys - Gly","Ser - Cys - Met","Asp - Cys - Val"],0,"Giải thích: Glutathion (GSH) là tripeptide gồm gamma-glutamyl-cysteinyl-glycin, chứa nhóm -SH của Cystein đóng vai trò khử peroxide và gốc tự do."],["Gramicidin S là một peptid kháng sinh do vi khuẩn Bacillus brevis sản xuất có đặc điểm cấu tạo đặc biệt nào?",["Chỉ chứa các acid amin dạng L","Là peptid vòng chứa cả acid amin dạng L và dạng D (D-Phe, L-Pro, L-Val, D-Orn, L-Leu)","Là một chuỗi polypeptide dài 500 aa","Không có liên kết peptid"],1,"Giải thích: Gramicidin S là peptid kháng sinh cấu trúc vòng chứa cả acid amin dạng L và dạng D (D-Phe, L-Pro, L-Val, D-Orn, L-Leu). Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Hormone Insulin là một hormon peptid gồm bao nhiêu chuỗi polypeptide và tổng cộng bao nhiêu acid amin?",["1 chuỗi, 29 acid amin","2 chuỗi (A và B), tổng cộng 51 acid amin","3 chuỗi, 86 acid amin","2 chuỗi, 100 acid amin"],1,"Giải thích: Insulin gồm 2 chuỗi polypeptide (chuỗi A 21 aa và chuỗi B 30 aa) nối với nhau bằng các cầu nối disulfide, tổng cộng 51 aa."],["Các neuropeptid như Enkephalin và Endorphin có chức năng sinh học chính là gì?",["Co bóp tử cung","Giảm đau tự nhiên và điều hòa cảm xúc","Tăng đường huyết","Thủy phân lipid"],1,"Giải thích: Enkephalin (5 aa) và Endorphin (15 aa) là các neuropeptid do tuyến yên và vùng hạ đồi tiết ra có tác dụng giảm đau opiat tự nhiên."],["Cấu hình phẳng của liên kết peptid (-CO-NH-) chủ yếu tồn tại ở dạng đồng phân nào do trở ngại không gian của các gốc R?",["Dạng Cis","Dạng Trans","Dạng xoắn alpha","Dạng zwitterion"],1,"Giải thích: Hầu hết các liên kết peptid trong protein đều tồn tại ở dạng Trans bền vững hơn hẳn dạng Cis do tránh tương tác đẩy giữa 2 gốc R kề nhau."],["Liên kết cộng hóa trị nào ngoài liên kết peptid giữ vai trò cực kỳ quan trọng trong việc duy trì cấu trúc bậc III của protein?",["Liên kết hydro","Liên kết Disulfide (-S-S- giữa 2 gốc Cysteine)","Liên kết ionic / muối","Tương tác Van der Waals"],1,"Giải thích: Liên kết disulfide (-S-S-) tạo thành giữa 2 nhóm -SH của 2 gốc Cysteine là liên kết cộng hóa trị thứ 2 duy trì cấu trúc không gian bậc 3 bền vững."],["Cấu trúc bậc I của protein được quyết định và duy trì chủ yếu bởi loại liên kết nào?",["Liên kết Hydro","Liên kết Peptid","Liên kết Disulfide","Tương tác kỵ nước"],1,"Giải thích: Cấu trúc bậc I là trình tự sắp xếp các gốc acid amin trong chuỗi polypeptide, được giữ vững bởi liên kết cộng hóa trị peptid."],["Cấu trúc bậc II của protein (xoắn alpha và nếp gấp beta) được ổn định chủ yếu nhờ loại liên kết nào?",["Liên kết Hydro giữa nhóm -C=O và -N-H của khung peptid","Liên kết Disulfide giữa các gốc R","Liên kết phosphat","Liên kết ester"],0,"Giải thích: Cấu trúc bậc II là sự xoắn hoặc gấp nếp tuần hoàn của chuỗi backbone, được duy trì bởi các liên kết Hydro giữa các nhóm -C=O và -NH của khung peptid."],["Lực tương tác nào đóng vai trò quan trọng nhất thúc đẩy sự xoắn cuộn chuỗi polypeptide tạo nên hình thể không gian 3 chiều (bậc III) trong môi trường nước?",["Liên kết peptid","Tương tác kỵ nước (giữa các gốc R không phân cực quay vào trong)","Phản ứng Biuret","Liên kết ester"],1,"Giải thích: Tương tác kỵ nước kéo các gốc R không phân cực tụ lại ở bên trong phân tử tránh tiếp xúc với nước là lực động lực chính tạo cấu trúc bậc 3."],["Cấu trúc bậc IV của protein có đặc điểm gì?",["Chuỗi polypeptide duỗi thẳng hoàn toàn","Sự kết hợp của 2 hay nhiều chuỗi polypeptide (tiểu đơn vị) có cấu trúc bậc III trong không gian","Chỉ bao gồm 1 chuỗi đơn duy nhất có chứa liên kết disulfide","Phá hủy toàn bộ liên kết peptid"],1,"Giải thích: Cấu trúc bậc IV là tổ hợp không gian của nhiều chuỗi polypeptide (subunit) độc lập (ví dụ Hemoglobin gồm 4 chuỗi alpha2-beta2)."],["Hiện tượng biến tính protein (Denaturation) là quá trình:",["Thủy phân hoàn toàn các liên kết peptid tạo acid amin tự do","Phá hủy các liên kết yếu (hydro, disulfide, muối, kỵ nước) làm mất cấu trúc bậc 2, 3, 4 nhưng liên kết peptid bậc 1 vẫn giữ nguyên","Tăng khả năng hòa tan của protein trong nước","Tổng hợp thêm chuỗi polypeptide mới"],1,"Giải thích: Biến tính protein làm đảo lộn cấu trúc không gian bậc cao (II, III, IV) do bẻ gãy các liên kết yếu, làm mất hoạt tính sinh học nhưng liên kết peptid bậc I không bị phá hủy."],["Yếu tố nào sau đây KHÔNG gây biến tính protein?",["Nhiệt độ cao (45 - 70°C)","Acid/Base mạnh, muối kim loại nặng","Dung dịch muối NaCl 0,9% (nước muối sinh lý) ở 37°C","Tia tử ngoại, chất tẩy rửa SDS, Urea 8M"],2,"Giải thích: Dung dịch muối sinh lý isotonic ở nhiệt độ cơ thể duy trì trạng thái tự nhiên của protein, không gây biến tính."],["Đặc điểm của quá trình biến tính hoàn nguyên (Reversible denaturation) là gì?",["Protein bị đông tụ vĩnh viễn như trứng luộc","Khi loại bỏ tác nhân biến tính (như urea, mercaptoethanol), protein phục hồi lại cấu trúc bậc cao và hoạt tính ban đầu","Liên kết peptid bị đứt gãy hoàn toàn","Protein chuyển từ dạng cầu sang dạng sợi không tan"],1,"Giải thích: Biến tính hoàn nguyên (ví dụ Ribonuclease xử lý bằng urea + mercaptoethanol) cho phép protein hồi phục lại cấu trúc 3D tự nhiên khi loại bỏ chất biến tính."],["Protein huyết tương đóng vai trò quan trọng nhất trong việc duy trì áp suất keo (khoảng 28 mmHg, chiếm 0,5% tổng áp suất thẩm thấu) của máu là:",["Fibrinogen","Albumin","Gamma-globulin","Actin"],1,"Giải thích: Albumin có nồng độ cao và kích thước vừa phải, giữ nước quanh phân tử tạo nên áp suất keo huyết tương duy trì thể tích máu."],["Nồng độ muối trung tính thấp (ví dụ NaCl 5%) làm tăng độ tan của protein được gọi là hiện tượng gì?",["Salting-out (diêm tích / kết tủa muối)","Salting-in (hòa tan bằng muối)","Thẩm tích","Biến tính không hoàn nguyên"],1,"Giải thích: Nồng độ muối thấp trung hòa bớt điện tích bề mặt giúp phân tử protein tương tác tốt hơn với nước -> tăng độ tan (Salting-in). Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Phương pháp diêm tích (Salting-out) sử dụng nồng độ muối cao (như Amoni sulfat (NH4)2SO4 bão hòa) dùng để làm gì trong sinh hóa?",["Phá hủy liên kết peptid","Kết tủa thuận nghịch protein để chiết xuất và tinh chế mà không làm mất hoạt tính","Biến tính vĩnh viễn protein","Định lượng tổng lượng nitơ"],1,"Giải thích: Nồng độ muối cao làm mất lớp vỏ hydration quanh protein làm chúng tụ lại kết tủa (Salting-out), đây là kết tủa thuận nghịch dùng tinh chế protein."],["Đặc điểm phân biệt giữa Protein thuần (Simple protein) và Protein tạp (Conjugated protein) là:",["Protein thuần chỉ chứa các acid amin, còn protein tạp ngoài phần protein thuần còn chứa nhóm ngoại (non-protein)","Protein thuần không có cấu trúc bậc III","Protein tạp không có liên kết peptid","Protein thuần không tan trong nước"],0,"Giải thích: Protein thuần thủy phân chỉ thu được acid amin; Protein tạp khi thủy phân tạo acid amin + nhóm ngoại (lipid, glucid, nhóm màu, kim loại...)."],["Loại protein tạp nào sau đây có nhóm ngoại là Porhyrin chứa Fe2+ đóng vai trò vận chuyển oxy?",["Nucleoprotein","Lipoprotein","Cromoprotein (Hemoglobin, Myoglobin)","Metalloprotein (Ferritin)"],2,"Giải thích: Hemoglobin và Myoglobin thuộc nhóm Cromoprotein (protein màu), có nhóm ngoại là Hem (Porphyrin + Fe2+)."],["Ferritin ở gan và lách chứa khoảng 20% Fe3+ thuộc lớp protein tạp nào?",["Glycoprotein","Metalloprotein (Protein kim loại)","Phosphoprotein","Lipoprotein"],1,"Giải thích: Ferritin là phức hợp dự trữ sắt của cơ thể, thuộc nhóm Metalloprotein."],["Mucoprotein có ở sụn, khớp và mô liên kết thuộc nhóm protein tạp nào?",["Lipoprotein","Glycoprotein (chứa nhóm ngoại mucopolysaccharide)","Nucleoprotein","Chromoprotein"],1,"Giải thích: Mucoprotein thuộc lớp Glycoprotein có chứa nhóm ngoại là carbohydrate phức hợp (mucopolysaccharide / glycosaminoglycan)."],["So với Protein hình cầu (Globular protein), Protein hình sợi (Fibrous protein) có đặc điểm gì?",["Dễ tan trong nước, nhạy cảm với pH","Không tan trong nước, bền vững với sự thay đổi pH và nhiệt độ, đóng vai trò nâng đỡ cấu trúc (Collagen, Keratin)","Thường đóng vai trò enzyme xúc tác","Đều là protein tạp"],1,"Giải thích: Protein sợi (Collagen, Keratin, Elastin) có chiều dài gấp nhiều lần chiều rộng, không tan trong nước, rất bền cơ học/hóa học đóng vai trò cấu trúc."],["Gluten là một hỗn hợp protein thực vật có trong lúa mì gồm prolamin và glutelin, có thể gây nên bệnh lý rối loạn hấp thu di truyền nào?",["Bệnh Celiac (dị ứng gluten)","Bệnh Pellagra","Bệnh Beriberi","Bệnh Wilson"],0,"Giải thích: Gluten thực vật có thể gây phản ứng miễn dịch tự hại ở niêm mạc ruột non dẫn đến bệnh Celiac."],["Kỹ thuật Thẩm tích (Dialysis) dựa trên tính chất nào của dung dịch keo protein để loại bỏ các phân tử muối khoáng nhỏ?",["Khả năng điện di của protein","Phân tử protein có kích thước lớn (1-100 nm) không đi qua được màng bán thấm, trong khi các ion muối nhỏ đi qua tự do","Phản ứng màu với Ninhydrin","Độ hấp thụ UV ở 280 nm"],1,"Giải thích: Thẩm tích lợi dụng việc hạt keo protein bị giữ lại bên trong túi màng bán thấm trong khi các phân tử muối nhỏ khuếch tán ra ngoài."],["Gốc acid amin Histidin đóng vai trò đệm pH quan trọng nhất trong hệ đệm protein của huyết tương do nhóm Imidazol có giá trị pKa bằng bao nhiêu?",["pKa ~ 2.1","pKa ~ 6.0 - 6.8 (gần pH sinh lý 7.4)","pKa ~ 10.5","pKa ~ 12.0"],1,"Giải thích: Nhóm Imidazol của Histidin có pKa khoảng 6.0 - 6.8, là nhóm duy nhất phân ly ở khoảng pH sinh lý (7.4) nên đóng vai trò đệm H+ hiệu quả."],["Enzyme Ribonuclease xúc tác thủy phân RNA thuộc nhóm phân loại protein theo chức năng nào?",["Protein vận chuyển","Protein xúc tác (Enzyme)","Protein bảo vệ","Protein dự trữ"],1,"Giải thích: Ribonuclease và Pepsin là các protein có chức năng enzyme xúc tác phản ứng sinh học."],["Các kháng thể (Immunoglobulin) trong huyết thanh thuộc nhóm protein chức năng nào?",["Protein vận động","Protein bảo vệ (Miễn dịch)","Protein điều hòa gen","Protein cấu trúc"],1,"Giải thích: Kháng thể (IgG, IgM, IgA...) được sản xuất bởi tế bào B/tương bào đóng vai trò protein bảo vệ miễn dịch cơ thể. B. PHẦN II: CHUYỂN HÓA PROTID (CÂU 51 DEN 120)"],["Ở người trưởng thành khỏe mạnh bình thường, trạng thái cân bằng nitơ (Nitrogen balance) xảy ra khi nào?",["Lượng Nitơ đưa vào lớn hơn lượng Nitơ thải ra","Lượng Nitơ đưa vào bằng lượng Nitơ thải ra (qua nước tiểu, phân, mồ hôi)","Lượng Nitơ thải ra lớn hơn lượng Nitơ đưa vào","Không có lượng Nitơ nào được đào thải"],1,"Giải thích: Ở người trưởng thành bình thường, lượng Nitơ nhập vào từ thức ăn bằng lượng Nitơ thải ra qua phân, nước tiểu, mồ hôi."],["Trạng thái Cân bằng Nitơ dương (Positive nitrogen balance) gặp trong trường hợp sinh lý nào sau đây?",["Bệnh nhân ung thư tiến triển, suy kiệt","Trẻ em đang lớn, phụ nữ có thai hoặc thời kỳ hồi phục sau bệnh","Sau phẫu thuật lớn, đói kéo dài","Người già yếu giảm vận động"],1,"Giải thích: Cân bằng Nitơ dương (N vào > N ra) gặp ở cơ thể đang phát triển mô mới như trẻ em đang lớn, phụ nữ mang thai, vận động viên tăng cơ. Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Enzyme Pepsinogen trong dịch dạ dày được kích hoạt thành Pepsin hoạt động nhờ tác nhân nào?",["Enterokinase và Trypsin","Acid HCl dịch vị và cơ chế tự xúc tác (Autocatalysis) của Pepsin","Bile salts (Muối mật)","Chymotrypsin"],1,"Giải thích: Pepsinogen được HCl cắt bỏ peptide ức chế để chuyển thành pepsin; pepsin vừa tạo thành lại tiếp tục kích thích tự hoạt hóa pepsinogen."],["Enzyme nào do niêm mạc ruột non tiết ra đóng vai trò mầm khởi động cắt bỏ đoạn peptide để hoạt hóa Trypsinogen của tụy thành Trypsin?",["Pepsin","Enterokinase (Enteropeptidase)","Carboxypeptidase","Aminopeptidase"],1,"Giải thích: Enterokinase do niêm mạc ruột tiết ra cắt chọn lọc trypsinogen tạo trypsin hoạt động; sau đó trypsin hoạt hóa chuỗi zymogen tụy khác."],["Enzyme tiêu hóa protein nào thuộc nhóm Exopeptidase (chỉ cắt liên kết peptid ở đầu tận chuỗi)?",["Pepsin và Trypsin","Chymotrypsin và Elastase","Aminopeptidase (cắt đầu N) và Carboxypeptidase (cắt đầu C)","Gelatinase"],2,"Giải thích: Aminopeptidase (cắt aa ở đầu N) và Carboxypeptidase A/B (cắt aa ở đầu C) là các Exopeptidase."],["Các L-acid amin giải phóng sau tiêu hóa được hấp thu tại tế bào niêm mạc ruột non theo cơ chế nào?",["Khuếch tán thụ động không tốn năng lượng","Vận chuyển tích cực thứ phát đồng vận chuyển với ion Na+ (tốn năng lượng ATP từ bơm Na+/K+-ATPase)","Lọc tự do qua các lỗ màng","Hấp thu nguyên phân tử protein bằng thực bào"],1,"Giải thích: L-acid amin được hấp thu tích cực qua màng bờ bàn chải tế bào niêm mạc ruột phụ thuộc đồng vận chuyển Na+ duy trì bởi bơm Na+/K+-ATPase."],["Cơ chế Khử carboxyl oxy hóa của acid amin tạo ra sản phẩm amin sinh học gì khi xúc tác bởi enzyme Histidine decarboxylase (coenzyme B6)?",["GABA","Histamin (gây co thắt phế quản, co mạch, tăng tính thấm mao mạch, tăng tiết HCl dạ dày)","Dopamine","Serotonin"],1,"Giải thích: Histidin bị khử carboxyl tạo Histamin - chất trung gian hóa học gây dị ứng, viêm, co thắt phế quản và kích thích tiết HCl."],["Sản phẩm khử carboxyl của Glutamat (xúc tác bởi Glutamate decarboxylase / B6) là chất nào có vai trò ức chế thần kinh trung ương?",["Histamin","GABA (Gamma-aminobutyric acid)","Tyramine","Cadaverine"],1,"Giải thích: Glutamat bị khử carboxyl tạo GABA - chất dẫn truyền thần kinh ức chế quan trọng trong não bộ."],["Quá trình thoái hóa nhóm alpha-amin (-NH2) của các acid amin ở động vật bậc cao diễn ra theo cơ chế chủ yếu nào?",["Khử amin oxy hóa trực tiếp tất cả 20 acid amin bởi L-amino acid oxidase","Khử amin oxy hóa gián tiếp (kết hợp phản ứng trao đổi amin Transamination và phản ứng khử amin L-Glutamate bởi GLDH)","Khử carboxyl hóa","Phản ứng Biuret"],1,"Giải thích: Động vật bậc cao khử amin gián tiếp: hầu hết aa chuyển nhóm -NH2 cho alpha-ketoglutarate tạo Glutamate; sau đó Glutamate bị khử amin trực tiếp bởi GLDH."],["Acid amin duy nhất ở động vật bậc cao có khả năng bị khử amin oxy hóa trực tiếp với tốc độ rất cao ở pH sinh lý nhờ enzyme Glutamate Dehydrogenase (GLDH) là:",["L-Alanine","L-Glutamate","L-Aspartate","L-Lysine"],1,"Giải thích: L-Glutamate là acid amin duy nhất có enzyme GLDH hoạt động rất mạnh ở pH sinh lý, sử dụng coenzyme NAD+ hoặc NADP+ để khử amin trực tiếp giải phóng NH4+."],["Phản ứng trao đổi amin (Transamination) xúc tác bởi các enzyme Transaminase (Aminotransferase) cần coenzyme bắt buộc nào?",["Thiamin pyrophosphate (TPP - B1)","Pyridoxal phosphate (PLP - Vitamin B6)","Niacin (NAD+ - B3)","Biotin (B7)"],1,"Giải thích: Tất cả các enzyme Transaminase đều sử dụng coenzyme Pyridoxal phosphate (PLP / Vitamin B6) để làm con thoi nhận và trao đổi nhóm amin."],["Enzyme ALT (Alanine aminotransferase) hay GPT xúc tác cho phản ứng trao đổi amin thuận nghịch giữa hai cặp chất nào?",["Glutamate + Oxaloacetate ⇌ Alpha-Ketoglutarate + Aspartate","Alanine + Alpha-Ketoglutarate ⇌ Pyruvate + Glutamate","Leucine + Pyruvate ⇌ Valine + Alanine","Serine + Pyruvate ⇌ Glycine + Oxaloacetate"],1,"Giải thích: ALT (GPT) chuyển nhóm amin giữa Alanine và alpha-Ketoglutarate tạo thành Pyruvate và Glutamate."],["Enzyme AST (Aspartate aminotransferase) hay GOT xúc tác cho phản ứng trao đổi amin nào?",["Aspartate + Alpha-Ketoglutarate ⇌ Oxaloacetate + Glutamate","Alanine + Oxaloacetate ⇌ Pyruvate + Aspartate","Glutamate + Pyruvate ⇌ Alpha-Ketoglutarate + Alanine","Glutamine + Pyruvate ⇌ Aspartate + Urea"],0,"Giải thích: AST (GOT) xúc tác trao đổi nhóm amin giữa Aspartate và alpha-Ketoglutarate tạo Oxaloacetate và Glutamate."],["Trong lâm sàng, sự tăng rất cao của enzyme ALT trong máu là chỉ thị tổn thương đặc hiệu nhất cho cơ quan nào?",["Cơ tim","Tế bào gan (Tế bào chất)","Thận","Tuyến tụy"],1,"Giải thích: ALT phân bố chủ yếu ở bào tương tế bào gan, do đó tăng ALT huyết tương là chỉ số có độ đặc hiệu cao nhất cho tổn thương hoại tử tế bào gan."],["NH3 độc đối với tế bào (đặc biệt là tế bào thần kinh não). Dạng vận chuyển NH3 không độc chủ yếu từ các mô (như cơ, não...) về gan và thận là:",["Urea","Glutamin (tổng hợp nhờ Glutamine synthetase + ATP)","Amoniac tự do (NH3)","Urat"],1,"Giải thích: NH3 được gắn vào Glutamate nhờ Glutamine synthetase (tốn 1 ATP) tạo thành Glutamine không độc theo máu vận chuyển an toàn đến gan và thận."],["Ở thận, enzyme Glutaminase thủy phân Glutamine giải phóng NH4+ có vai trò sinh lý quan trọng nào?",["Tổng hợp Glucose","Đào thải H+ trung hòa acid, tham gia điều hòa cân bằng acid-base của cơ thể","Tạo chu trình urea tại thận","Khử độc bilirubin"],1,"Giải thích: Ở thận, Glutaminase thủy phân Gln -> Glu + NH4+. NH3 kết hợp H+ thành NH4+ thải ra nước tiểu, giúp loại bỏ H+ và duy trì cân bằng kiềm toan. Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Chu trình Glucose - Alanine đóng vai trò quan trọng trong việc vận chuyển Nitơ từ cơ quan nào về gan?",["Từ Não về Gan","Từ Cơ vân (Muscle) về Gan","Từ Thận về Gan","Từ Ruột về Gan"],1,"Giải thích: Ở cơ, NH3 được chuyển sang Pyruvate tạo Alanine. Alanine theo máu về gan thoái hóa trả lại Pyruvate tân tạo Glucose, đồng thời giao NH3 cho chu trình Urea."],["Cơ quan duy nhất trong cơ thể có đầy đủ hệ thống enzyme để thực hiện trọn vẹn chu trình Urea (Krebs-Henseleit) tổng hợp urea đào thải ra máu là:",["Thận","Gan (Tế bào gan)","Cơ vân","Não"],1,"Giải thích: Gan là cơ quan duy nhất chứa đủ enzyme (đặc biệt là Arginase) để tổng hợp urea từ NH3."],["Chu trình Urea diễn ra ở những vị trí phân tử nào bên trong tế bào gan?",["Hoàn toàn ở Bào tương (Cytosol)","Giai đoạn đầu (Phản ứng 1, 2) trong Ti thể và giai đoạn sau (Phản ứng 3, 4, 5) trong Bào tương","Hoàn toàn trong Ti thể","Trong Nhân tế bào"],1,"Giải thích: Phản ứng 1 (tạo Carbamoyl phosphate) và Phản ứng 2 (tạo Citrulline) diễn ra trong chất nền Ti thể; Citrulline ra Bào tương thực hiện PỨ 3, 4, 5."],["Phản ứng 1 của chu trình Urea tổng hợp Carbamoyl phosphate từ NH4+ và HCO3- trong ti thể nhờ enzyme Carbamoyl Phosphate Synthetase I (CPS-I) tiêu tốn bao nhiêu ATP?",["1 ATP","2 ATP","3 ATP","4 ATP"],1,"Giải thích: Phản ứng 1 tổng hợp Carbamoyl phosphate cần 2 phân tử ATP (cùng chất hoạt hóa bắt buộc N-acetylglutamate - AGA)."],["Chất điều hòa dị lập thể dương (hoạt hóa bắt buộc) đối với enzyme CPS-I kiểm soát tốc độ chung của chu trình Urea là:",["Citrate","N-acetylglutamate (AGA)","ATP","Fumarate"],1,"Giải thích: N-acetylglutamate (tổng hợp từ Acetyl-CoA và Glutamate bởi AGA synthase) là chất hoạt hóa bắt buộc của enzyme CPS-I."],["Trong phản ứng 2 của chu trình Urea, Carbamoyl phosphate ngưng tụ với hợp chất nào trong ti thể để tạo thành Citrulline rời ti thể ra bào tương?",["L-Ornithine (xúc tác bởi Ornithine transcarbamoylase - OTC)","L-Arginine","Aspartate","Oxaloacetate"],0,"Giải thích: Carbamoyl phosphate + L-Ornithine -> L-Citrulline + Pi nhờ enzyme OTC trong ti thể."],["Nguyên tử Nitơ thứ hai đi vào cấu trúc phân tử Urea ở phản ứng 3 trong bào tương được cung cấp trực tiếp từ acid amin nào?",["Glutamine","L-Aspartate (ngưng tụ với Citrulline tốn 1 ATP -> AMP + PPi)","Alanine","Glycine"],1,"Giải thích: Phản ứng 3: Citrulline + L-Aspartate -> Argininosuccinate (nhờ Argininosuccinate synthetase), Aspartate cung cấp nguyên tử N thứ 2."],["Phản ứng 4 phân cắt Argininosuccinate giải phóng Arginine và hợp chất trung gian nào tạo cầu nối liên kết giữa chu trình Urea và chu trình Krebs (Acid citric)?",["Succinate","Fumarate","Malate","Pyruvate"],1,"Giải thích: Argininosuccinate bị cắt giải phóng Arginine và Fumarate. Fumarate đi vào ti thể tham gia chu trình Krebs (Cầu nối Krebs - Urea)."],["Ở phản ứng 5 của chu trình Urea, enzyme Arginase thủy phân Arginine tạo ra Urea và tái sinh chất nào để tiếp tục đi vào ti thể khởi đầu chu trình mới?",["L-Ornithine","Citrulline","Carbamoyl phosphate","Glutamate"],0,"Giải thích: Arginase thủy phân Arginine + H2O -> Urea (đào thải) + L-Ornithine (đi ngược vào ti thể tiếp tục vòng lặp)."],["Tính tổng cộng toàn bộ chu trình Urea tiêu tốn tương đương bao nhiêu liên kết cao năng ATP để tổng hợp nên 1 phân tử Urea?",["2 ATP","3 ATP (tương đương 4 liên kết phosphate cao năng: 2 ATP ở PỨ 1 thành 2 ADP + 1 ATP ở PỨ 3 thành AMP + PPi)","5 ATP","Không tiêu tốn ATP"],1,"Giải thích: Phương trình tổng quát: 2 NH4+ + HCO3- + 3 ATP + H2O -> Urea + 2 ADP + 4 Pi + AMP + 2 H+. Tổng cộng tiêu tốn 4 liên kết cao năng (~3 ATP)."],["Nồng độ Urea bình thường trong máu người trưởng thành khoảng bao nhiêu?",["0,05 - 0,1 g/L","0,2 - 0,5 g/L (tương đương 3,3 - 8,3 mmol/L)","1,0 - 2,0 g/L","5,0 - 10,0 g/L"],1,"Giải thích: Nồng độ Urea máu bình thường dao động 0,2 - 0,5 g/L (3,3 - 8,3 mmol/L)."],["Trường hợp nào sau đây gây TĂNG urea máu nguồn gốc trước thận?",["Viêm cầu thận cấp","Hủy hoại mô/protein mạnh (bỏng rộng, chấn thương) hoặc giảm lưu lượng máu đến thận (suy tim, mất máu/mất nước nặng)","Tắc nghẽn niệu quản do sỏi","Suy gan nặng, xơ gan"],1,"Giải thích: Tăng urea trước thận do tăng thoái hóa protid (bỏng, chấn thương) hoặc giảm tưới máu thận (suy tim, mất nước, nôn ói)."],["Trường hợp nào sau đây gây GIẢM nồng độ urea máu?",["Suy thận mạn giai đoạn cuối","Tổn thương gan nặng (xơ gan, viêm gan cấp làm giảm tổng hợp) hoặc chế độ ăn thiếu protid lâu ngày, phụ nữ mang thai","Sỏi tiền liệt tuyến gây tắc niệu đạo","Xuất huyết tiêu hóa cao"],1,"Giải thích: Giảm urea máu do gan giảm tổng hợp (suy gan, xơ gan), ăn thiếu protein lâu ngày, hòa loãng máu hoặc phụ nữ có thai."],["Khiếm khuyết bẩm sinh di truyền enzyme OTC (Ornithine transcarbamoylase) thuộc chu trình Urea có đặc điểm di truyền nào khác biệt với các enzyme khác trong chu trình?",["Di truyền lặn trên nhiễm sắc thể thường (AR)","Di truyền liên kết nhiễm sắc thể giới tính X (X-linked)","Di truyền trội trên nhiễm sắc thể thường (AD)","Di truyền qua ty thể"],1,"Giải thích: Thiếu hụt OTC di truyền liên kết NST giới tính X (X-linked), trong khi thiếu hụt các enzyme chu trình urea khác (CPS1, ASS1, ASL, ARG1) di truyền lặn NST thường. Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Các acid amin sau khi khử amin tạo ra sườn carbon (alpha-cetonic acid). Acid amin nào sau đây thuộc nhóm CHỈ sinh Ceton (Ketogenic only)?",["Alanine và Glycine","Leucin và Lysin","Glutamate và Aspartate","Valine và Serine"],1,"Giải thích: Leucin và Lysin là 2 acid amin thuần túy chỉ thoái hóa tạo Acetyl-CoA/Acetoacetyl-CoA (sinh ceton), không thể dùng tân tạo đường."],["Acid amin Tryptophan là tiền chất quan trọng để sinh tổng hợp các chất có hoạt tính sinh học nào?",["Serotonin (chất dẫn truyền thần kinh) và Melatonin (hormone nhịp sinh học)","Epinephrine và Norepinephrine","Thyroxine (T3, T4)","Histamin"],0,"Giải thích: Tryptophan là tiền chất tổng hợp Serotonin, Melatonin và Vitamin B3 (Niacin)."],["Thiếu hụt Vitamin B3 (Niacin/PP) hoặc suy giảm chuyển hóa Tryptophan sinh Niacin dẫn đến bệnh lý lâm sàng đặc trưng nào?",["Bệnh Beriberi (tê phù)","Bệnh Pellagra (tam chứng: Viêm da nhạy cảm ánh sáng, Tiêu chảy, Sa sút trí tuệ)","Bệnh Còi xương","Bệnh Scorbut"],1,"Giải thích: Thiếu Niacin/Tryptophan gây bệnh Pellagra với 3 triệu chứng điển hình D: Dermatitis (viêm da), Diarrhea (tiêu chảy), Dementia (sa sút trí tuệ)."],["Chuỗi phản ứng thoái hóa của Phenylalanin và Tyrosin ở người sinh tổng hợp ra nhóm hormone đáp ứng stress Catecholamin gồm những chất nào?",["Insulin và Glucagon","Dopamin, Noradrenalin (Norepinephrine) và Adrenalin (Epinephrine)","Cortisol và Aldosterone","Melatonin và Oxytocin"],1,"Giải thích: Phenylalanin -> Tyrosin -> DOPA -> Dopamine -> Noradrenalin -> Adrenalin (nhóm Catecholamin)."],["Bệnh di truyền Phenylketon niệu (PKU) do thiếu hụt bẩm sinh enzyme nào dẫn đến tích tụ Phenylalanin gây nhiễm độc thần kinh và sa sút trí tuệ ở trẻ sơ sinh?",["Tyrosinase","Phenylalanine hydroxylase (PAH)","Homogentisate oxidase","Fumarylacetoacetate hydrolase"],1,"Giải thích: PKU do đột biến gen mã hóa Phenylalanine hydroxylase không chuyển Phenylalanine thành Tyrosine được, gây tích tụ acid phenylpyruvic tổn thương não."],["Bệnh Alkapton niệu (Alkaptonuria) do thiếu hụt enzyme Homogentisate oxidase dẫn đến sự tích tụ acid homogentisic có biểu hiện lâm sàng đặc trưng nào?",["Nước tiểu hóa đen khi để ngoài không khí và lắng đọng sắc tố gây viêm khớp","Bạch tạng bạch biến da tóc","Còi xương suy dinh dưỡng","Co giật tím tái"],0,"Giải thích: Alkaptonuria do bộc phát acid homogentisic bị oxy hóa hóa màu đen trong nước tiểu để ngoài không khí và gây thoái hóa khớp."],["Bệnh Bạch tạng (Albinism) xuất hiện do thiếu hụt bẩm sinh enzyme nào trong con đường chuyển hóa Tyrosine thành sắc tố?",["Tyrosinase (Tyrosine 3-monooxygenase)","Phenylalanine hydroxylase","GLDH","Arginase"],0,"Giải thích: Bạch tạng do thiếu enzyme Tyrosinase xúc tác tổng hợp sắc tố Melanin từ DOPA/Tyrosine làm da, tóc có màu trắng và mắt màu hồng."],["Bệnh Xi-rô niệu (Maple syrup urine disease - MSUD) do suy giảm phức hợp enzyme thoái hóa chuỗi alpha-cetoacid của nhóm acid amin nào?",["Các acid amin mạch nhánh (Leucin, Isoleucin, Valin)","Các acid amin nhân thơm (Phe, Tyr, Trp)","Các acid amin chứa lưu huỳnh (Cys, Met)","Các acid amin dicarboxylic"],0,"Giải thích: MSUD do thiếu hụt phức hợp enzyme đệm thoái hóa alpha-keto acid của 3 acid amin mạch nhánh (Leu, Ile, Val), nước tiểu có mùi đặc trưng như siro cây phong."],["Quá trình tổng hợp Creatine diễn ra ở hai cơ quan nào và cần sự tham gia của 3 acid amin nào?",["Giai đoạn 1 ở Thận (AGAT), Giai đoạn 2 ở Gan (GAMT); từ 3 aa: Arginine, Glycine, Methionine (SAM)","Giai đoạn 1 ở Gan, Giai đoạn 2 ở Cơ; từ Ala, Ser, Cys","Diễn ra hoàn toàn ở Não; từ Glu, Asp, Gln","Diễn ra ở Lách; từ His, Trp, Lys"],0,"Giải thích: Creatine được tổng hợp qua 2 bước: Bước 1 ở Thận (Arginine + Glycine -> Guanidinoacetate nhờ AGAT), Bước 2 ở Gan (chuyển nhóm methyl từ SAM nhờ GAMT)."],["S-adenosylmethionine (SAM) được tạo thành từ Methionine và ATP có vai trò sinh học quan trọng nhất là gì?",["Cung cấp nhóm phosphate cao năng","Chất cho nhóm Methyl (-CH3) hoạt hóa trong các phản ứng methyl hóa (tổng hợp Creatine, Adrenalin, Phosphatidylcholine...)","Khử độc NH3","Vận chuyển oxy"],1,"Giải thích: SAM chứa liên kết lưu huỳnh cao năng mang nhóm -CH3 hoạt hóa linh động cho các phản ứng methyl hóa trong tế bào."],["Cơ thể người và động vật có xương sống chỉ có khả năng tự tổng hợp khoảng bao nhiêu acid amin?",["5 acid amin","10 - 12 acid amin (acid amin không thiết yếu)","Tất cả 20 acid amin","0 acid amin"],1,"Giải thích: Người và động vật cao cấp chỉ tự tổng hợp được 10-12 acid amin không thiết yếu từ sườn carbon của đường phân và chu trình Krebs."],["Hai acid amin nào được coi là 'bán thiết yếu' (semi-essential) vì cơ thể người lớn tổng hợp đủ nhưng trẻ em đang phát triển tổng hợp không đáp ứng đủ nhu cầu?",["Valin và Leucin","Histidin và Arginin","Phenylalanin và Tryptophan","Lysin và Methionin"],1,"Giải thích: Histidin và Arginin là 2 aa bán thiết yếu (trẻ nhỏ cần bổ sung thêm từ thức ăn do tốc độ tổng hợp nội sinh chưa đáp ứng kịp sự lớn lên)."],["Khung hydrocarbon để sinh tổng hợp các acid amin không thiết yếu ở người được lấy từ các đường hướng chuyển hóa trung gian nào?",["Đường phân (Glycolysis), Chu trình Krebs (TCA) và Con đường Pentose Phosphate","Chu trình Urea","Chu trình Beta-oxy hóa acid béo","Chu trình Coris"],0,"Giải thích: Sườn cacbon tổng hợp aa được rút ra từ sản phẩm trung gian của Đường phân (Pyruvate, 3-PG), Chu trình Krebs (OAA, alpha-KG) và Pentose Phosphate (Erythrose 4-P, Ribose 5-P)."],["Phản ứng amin hóa alpha-Ketoglutarate gắn trực tiếp NH4+ giải phóng nước để tái tạo Glutamate xúc tác bởi GLDH cần đương lượng khử nào ở vi khuẩn và thực vật?",["ATP","NADPH","FADH2","Coenzyme A"],1,"Giải thích: Phản ứng amin hóa khử oxy tổng hợp Glutamate ở thực vật và vi khuẩn sử dụng coenzyme NADPH. Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Glutathion ở dạng khử (GSH) trung hòa điện tích các gốc tự do ROS/RNS bằng cách cho nguyên tử H từ nhóm chức nào của Cysteine?",["Nhóm -COOH","Nhóm Thiol (-SH)","Nhóm -NH2","Nhóm Hydroxyl"],1,"Giải thích: Nhóm -SH của Cysteine trong GSH nhường H+ và electron khử hydroperoxide thành nước, chuyển GSH thành dạng oxy hóa GSSG nối bằng cầu disulfide."],["Enzyme Glutathione reductase sử dụng chất nào để biến đổi dạng oxy hóa GSSG trở lại dạng khử GSH phục hồi khả năng chống oxy hóa?",["NADH","NADPH, H+ (tạo ra chính từ con đường Pentose Phosphate)","ATP","Vitamin C"],1,"Giải thích: Glutathione reductase cần NADPH (chủ yếu từ đường Pentose Phosphate) để tái tạo GSSG thành 2 GSH."],["Quá trình tổng hợp Glutathion tại tế bào gan gồm 2 bước tiêu tốn bao nhiêu phân tử ATP?",["Không tốn ATP","2 ATP (PỨ 1 tạo gamma-glutamylcysteine + PỨ 2 gắn Glycine)","4 ATP","6 ATP"],1,"Giải thích: Tổng hợp GSH gồm 2 bước xúc tác bởi gamma-glutamylcysteine ligase và glutathione synthetase, mỗi bước tiêu tốn 1 ATP (tổng 2 ATP)."],["Hiện tượng ức chế dị lập thể ngược (Feedback inhibition) trong điều hòa sinh tổng hợp acid amin có cơ chế ra sao?",["Sản phẩm cuối cùng của chuỗi phản ứng quay lại ức chế enzyme đầu tiên xúc tác cho con đường đó","Nguyên liệu đầu tiên ức chế sản phẩm cuối","Enzyme bị phân hủy bởi protease","Tăng phiên mã gen xúc tác"],0,"Giải thích: Điều hòa tổng hợp aa thường theo cơ chế ức chế ngược dị lập thể: sản phẩm aa hình thành đủ sẽ gắn và ức chế enzyme chìa khóa ở nấc đầu tiên."],["Nồng độ Creatinine huyết thanh bình thường là một chỉ số phản ánh chính xác chức năng lọc của cơ quan nào?",["Gan","Thận (Cầu thận)","Tuyến tụy","Tim"],1,"Giải thích: Creatinine thoái hóa tự phát từ Phosphocreatine cơ bắp với tốc độ hằng định, được lọc tự do qua cầu thận và không bị tái hấp thu đáng kể, nên là chỉ số đánh giá GFR của thận."],["Acid amin Alanine được vận chuyển từ tế bào cơ về gan để làm nguyên liệu cho quá trình tân tạo hợp chất nào?",["Glycogen / Glucose","Triglyceride","Cholesterol","DNA"],0,"Giải thích: Ở gan, Alanine bị trao đổi amin trả lại Pyruvate, Pyruvate đi vào đường tân tạo đường tổng hợp nên Glucose."],["Tyrosin là tiền chất trực tiếp để tổng hợp nhóm hormone tuyến giáp nào?",["Insulin và Glucagon","Triiodothyronine (T3) và Thyroxine (T4)","Calcimimetic","Parathyroid hormone (PTH)"],1,"Giải thích: Tyrosin gắn iod tạo MIT và DIT, ngưng tụ lại thành T3 (Triiodothyronine) và T4 (Thyroxine) ở tuyến giáp."],["Giai đoạn đầu tiên của chu trình Urea diễn ra ở đâu?",["Xảy ra trong Ti thể tế bào gan","Xảy ra ở Bào tương tế bào thận","Xảy ra ở Màng tế bào ruột","Xảy ra trong Lysosome"],0,"Giải thích: 2 phản ứng đầu của chu trình urea diễn ra trong chất nền Ti thể của tế bào gan."],["Enzyme Ornithine transcarbamoylase (OTC) xúc tác phản ứng ngưng tụ L-Ornithine với hợp chất nào?",["Carbamoyl phosphate","Oxaloacetate","Aspartate","Succinyl-CoA"],0,"Giải thích: OTC trong ti thể ngưng tụ Carbamoyl phosphate với L-Ornithine tạo L-Citrulline."],["N-acetylglutamate (AGA) được tổng hợp từ hai chất tiền chất nào nhờ enzyme N-acetylglutamate synthase?",["Acetyl-CoA và Glutamate (được kích thích bởi Arginine)","Pyruvate và Aspartate","Oxaloacetate và Alanine","Citrate và Glutamine"],0,"Giải thích: N-acetylglutamate được tạo thành từ Acetyl-CoA và Glutamate, phản ứng này được hoạt hóa bởi Arginine."],["Trong phản ứng khử amin oxy hóa của L-Glutamate bởi GLDH, coenzyme nào được sử dụng phổ biến nhất trong con đường THOÁI HÓA ở động vật bậc cao?",["FAD","NAD+","NADPH","Biotin"],1,"Giải thích: Ở động vật cao cấp, phản ứng thoái hóa L-Glutamate giải phóng NH3 ưu tiên dùng coenzyme NAD+."],["Dạng amoniac độc NH3 tự do trong máu khuếch tán qua màng tế bào não gây tổn thương não theo cơ chế nào?",["Gắn vào Hemoglobin ngăn gắn oxy","Kéo alpha-Ketoglutarate ra khỏi chu trình Krebs để gắn NH3 tạo Glutamate/Glutamine, gây suy kiệt năng lượng ATP của tế bào não","Phá hủy myelin","Tăng tổng hợp Glucose"],1,"Giải thích: NH3 cao trong não thúc đẩy gắn NH3 vào alpha-Ketoglutarate -> cạn kiệt alpha-KG của chu trình Krebs làm dừng tạo ATP ở não gây hôn mê gan."],["Trường hợp bệnh nhân bị suy gan nặng (xơ gan giai đoạn cuối), sự tích tụ chất nào trong máu có nguy cơ dẫn tới Hôn mê gan (Hepatic encephalopathy)?",["Glucose","NH3 / NH4+ (Amoniac máu tăng cao)","Cholesterol","Urea"],1,"Giải thích: Suy gan giảm khả năng tổng hợp urea làm tăng NH3 máu, NH3 ngấm qua hàng rào máu não gây nhiễm độc thần kinh và hôn mê gan."],["Một bệnh nhân bị bỏng diện rộng nghiêm trọng sẽ có sự thay đổi chỉ số Nitơ và Urea máu như thế nào?",["Cân bằng Nitơ dương, Urea máu giảm","Cân bằng Nitơ âm (do dị hóa protein mô tăng mạnh), Urea máu tăng trước thận","Cân bằng Nitơ không đổi","Urea máu bằng 0"],1,"Giải thích: Bỏng rộng gây hủy hoại mô dị hóa protein cực mạnh -> Cân bằng Nitơ âm và làm tăng Urea máu nguồn gốc trước thận. Tài liệu Học tập & Ôn thi Chuyên đề Protid"],["Tỷ số AST/ALT (Chỉ số De Ritis) bình thường trong máu khoảng bao nhiêu?",["0,1 - 0,2","~ 1,15 (hoặc 0,8 - 1,2)","> 5,0","< 0,01"],1,"Giải thích: Chỉ số De Ritis bình thường AST/ALT xấp xỉ 1.15. Trong viêm gan cấp do virus ALT tăng cao hơn AST nên tỷ số < 1; trong tổn thương tế bào gan do rượu/xơ gan AST tăng cao hơn ALT nên tỷ số > 2."],["Enzyme nào thoái hóa nhóm amin của acid amin gián tiếp thông qua việc chuyển nhóm amin sang cho Pyruvate?",["ALT (GPT) tạo Alanine","AST (GOT) tạo Aspartate","GLDH","Arginase"],0,"Giải thích: ALT chuyển nhóm amin từ acid amin sang Pyruvate tạo Alanine."],["Phương trình phản ứng tổng hợp Urea tiêu tốn 1 phân tử Aspartate ở phản ứng 3. Aspartate này được tái tạo lại từ Fumarate thông qua các bước của chu trình nào?",["Fumarate -> Malate -> Oxaloacetate (chu trình Krebs) -> Aspartate (qua phản ứng trao đổi amin với Glutamate)","Fumarate -> Pyruvate -> Alanine","Fumarate -> Citrate -> Succinate","Fumarate -> Lactate"],0,"Giải thích: Fumarate giải phóng ở PỨ 4 biến thành Malate -> Oxaloacetate trong ti thể, sau đó OAA nhận amin từ Glutamate tạo Aspartate tái sử dụng cho PỨ 3."],["Chất nào sau đây vừa là sản phẩm trung gian của chu trình Krebs vừa là sản phẩm giải phóng từ phản ứng phân cắt Argininosuccinate ở chu trình Urea?",["Oxaloacetate","Fumarate","Alpha-Ketoglutarate","Citrate"],1,"Giải thích: Fumarate được tạo ra ở PỨ 4 chu trình Urea và cũng là một chất trung gian của chu trình Krebs."],["Nhóm acid amin nào sau đây gồm các acid amin VỪA sinh đường VỪA sinh ceton?",["Leu và Lys","Isoleucine, Phenylalanine, Tryptophan, Tyrosine","Ala, Gly, Ser, Val","Asp, Glu, Gln, Asn"],1,"Giải thích: Ile, Phe, Trp, Tyr (cùng Thr) thuộc nhóm acid amin vừa sinh đường vừa sinh ceton."],["Trong chu trình Urea, enzyme nào xúc tác cho phản ứng ngưng tụ Citrulline với Aspartate tại bào tương?",["Argininosuccinate synthetase","Argininosuccinate lyase","CPS-I","OTC"],0,"Giải thích: Argininosuccinate synthetase ngưng tụ Citrulline + Aspartate + ATP -> Argininosuccinate + AMP + PPi."],["Loại vi khuẩn đường ruột sản sinh enzyme Urease thủy phân Urea trong lòng ruột tạo ra chất nào ngấm vào máu tĩnh mạch cửa về gan?",["NH3 và CO2","Glutamine","Creatine","Amino acid"],0,"Giải thích: Vi khuẩn ruột chứa urease thủy phân urea thành NH3 và CO2, NH3 ngấm vào máu về gan."],["Homocysteine là một sản phẩm trung gian trong chu trình thoái hóa của acid amin nào, nếu tăng cao trong máu sẽ là yếu tố nguy cơ độc lập của bệnh tim mạch?",["Methionine","Lysine","Valine","Tryptophan"],0,"Giải thích: Methionine thoái hóa qua SAM -> SAH -> Homocysteine. Tăng Homocysteine máu gây tổn thương nội mạc mạch máu tăng nguy cơ xơ vữa và huyết khối."],["Enzyme Cystathionine beta-synthase (CBS) chuyển Homocysteine thành Cystathionine cần vitamin coenzyme nào (thiếu hụt gây bệnh Homocystin niệu)?",["Vitamin B6 (Pyridoxal phosphate)","Vitamin C","Vitamin A","Vitamin K"],0,"Giải thích: CBS cần Vitamin B6 làm coenzyme. Thiếu B6 hoặc gen CBS gây bệnh Homocystinuria tích tụ Homocysteine gây biến dạng xương và sa sút trí tuệ."],["Chất nào sau đây được coi là sản phẩm đào thải nitơ chính yếu nhất của cơ thể người (chiếm khoảng 80% tổng Nitơ nước tiểu)?",["Acid uric","Urea","Creatinine","NH4+"],1,"Giải thích: Urea là sản phẩm đào thải nitơ chính yếu của cơ thể người (chiếm khoảng 80% lượng Nitơ trong nước tiểu)."],["Bệnh Homocystin niệu (Homocystinuria) do đột biến gen Cystathionine beta-synthase có nguy cơ gây ra hậu quả nào?",["Biến dạng xương, suy giảm trí tuệ và tăng nguy cơ huyết khối tắc mạch sớm","Vàng da nhân","Xuất huyết kéo dài","Tăng huyết áp cấp"],0,"Giải thích: Homocystinuria gây tích tụ Homocysteine dẫn đến lệch thủy tinh thể, biến dạng xương dạng Marfan, chậm phát triển trí tuệ và huyết khối mạch máu."],["Tổng cộng quá trình tiêu hóa và chuyển hóa protid duy trì cân bằng nội môi cơ thể. Khái niệm 'Body amino acid pool' (Quỹ acid amin tự do của cơ thể) có khối lượng trung bình khoảng bao nhiêu?",["Khoảng 100 g","Khoảng 1000 g","Khoảng 10 kg","Khoảng 1 g"],0,"Giải thích: Quỹ acid amin tự do toàn cơ thể (Body amino acid pool) duy trì trạng thái động khoảng 100g, trao đổi liên tục giữa protein thức ăn, thoái hóa protein nội bào và tổng hợp mới. Tài liệu Học tập & Ôn thi Chuyên đề Protid"]];
const NUCLEOTIDE=[["Thành phần hóa học cấu tạo nên một phân tử Nucleotide hoàn chỉnh bao gồm:",["Base nitơ, đường Pentose và Acid phosphoric","Base nitơ, đường Hexose và Acid phosphoric","Base nitơ và đường Pentose","Đường Pentose và nhóm Phosphate"],0,"Lời giải: Một nucleotide gồm 3 thành phần chính: 1 base nitơ (purine hoặc pyrimidine), 1 đường 5 carbon (pentose: ribose hoặc deoxyribose) và 1-3 nhóm acid phosphoric (phosphate)."],["Sự khác biệt về mặt cấu trúc giữa Nucleoside và Nucleotide là gì?",["Nucleoside không có base nitơ","Nucleoside không có nhóm acid phosphoric","Nucleotide không có đường pentose","Nucleoside chứa đường hexose còn nucleotide chứa đường pentose"],1,"Lời giải: Nucleoside chỉ gồm Base nitơ liên kết với Đường pentose (bằng liên kết β,N-glycoside). Khi nucleoside gắn thêm nhóm phosphate thì trở thành Nucleotide."],["Các base nitơ thuộc nhóm Purine có trong thành phần của acid nucleic bao gồm:",["Cytosine, Thymine, Uracil","Adenine, Guanine","Adenine, Cytosine","Guanine, Thymine"],1,"Lời giải: Nhóm Purine gồm hai base chính có mặt ở cả DNA và RNA là Adenine (A) và Guanine (G). Nhóm Pyrimidine gồm Cytosine (C), Thymine (T) và Uracil (U)."],["Base nitơ nào sau đây CHỈ có trong cấu trúc của RNA mà KHÔNG có trong DNA?",["Cytosine","Thymine","Uracil","Adenine"],2,"Lời giải: Uracil (U) chỉ xuất hiện trong RNA. Trong DNA, vị trí tương ứng là Thymine (T - bản chất là 5-methyluracil)."],["Base nitơ nào sau đây CHỈ có trong cấu trúc của DNA mà KHÔNG có trong RNA?",["Uracil","Thymine","Guanine","Cytosine"],1,"Lời giải: Thymine (T) đặc trưng cho phân tử DNA, không có mặt trong RNA tiêu chuẩn."],["Đường Pentose có trong phân tử RNA là:",["2'-Deoxy-D-ribose","D-Ribose","D-Glucose","D-Fructose"],1,"Lời giải: RNA chứa đường D-Ribose (có nhóm -OH ở vị trí C2'). DNA chứa 2'-Deoxy-D-ribose (thiếu 1 nguyên tử oxy ở C2')."],["Đường 2'-Deoxy-D-ribose trong DNA khác với D-Ribose trong RNA ở điểm nào?",["Thiếu nhóm -OH ở carbon số 3'","Thiếu nhóm -OH ở carbon số 2'","Có thêm nhóm -CH3 ở carbon số 5'","Thiếu nhóm -OH ở carbon số 1'"],1,"Lời giải: Đường 2'-deoxyribose mất 1 nguyên tử oxy ở vị trí carbon C2' (chỉ còn nguyên tử H thay vì nhóm -OH như ở ribose)."],["Liên kết β,N-glycoside trong phân tử Nucleoside được hình thành giữa carbon C1' của đường pentose với nguyên tử N nào của base nitơ?",["N1 của Purine và N9 của Pyrimidine","N9 của Purine và N1 của Pyrimidine","N3 của Purine và N3 của Pyrimidine","N7 của Purine và N1 của Pyrimidine"],1,"Lời giải: Liên kết β,N-glycoside nối C1' của đường pentose với N9 đối với các base vòng đôi Purine (A, G) và với N1 đối với các base vòng đơn Pyrimidine (C, T, U)."],["Tên gọi chính xác của nucleoside tạo bởi base Adenine và đường D-ribose là:",["Adenylate","Adenosine","Deoxyadenosine","Adenic acid"],1,"Lời giải: Base Purine + Ribose có tên gọi đuôi '-osine' -> Adenine + Ribose = Adenosine."],["Tên gọi chính xác của nucleoside tạo bởi base Cytosine và đường D-ribose là:",["Cytidylate","Cytidine","Deoxycytidine","Cytosinoside"],1,"Lời giải: Base Pyrimidine + Ribose có tên gọi đuôi '-idine' -> Cytosine + Ribose = Cytidine."],["Khi base Thymine liên kết với đường 2'-deoxyribose, nucleoside tạo thành thường được gọi ngắn gọn là:",["Thymidine","Deoxythyminoside","Thymine riboside","Thymidylate"],0,"Lời giải: Vì Thymine hầu như chỉ liên kết với Deoxyribose trong tự nhiên, phân tử deoxythymidine thường được gọi đơn giản là Thymidine."],["Trong phân tử Nucleotide, nhóm acid phosphoric liên kết với đường pentose qua liên kết loại nào và ở vị trí carbon mấy?",["Liên kết Glycoside ở carbon C1'","Liên kết Ester (phosphoester) ở carbon C5'","Liên kết Anhydride ở carbon C3'","Liên kết Peptide ở carbon C2'"],1,"Lời giải: Nhóm phosphate nối với nhóm -OH ở vị trí carbon C5' của đường pentose bằng liên kết phosphoester."],["Phân tử ATP (Adenosine triphosphate) chứa bao nhiêu liên kết anhydride phosphat (liên kết cao năng)?",["1 liên kết","2 liên kết","3 liên kết","Không có liên kết cao năng"],1,"Lời giải: ATP có 1 liên kết phosphoester (giữa C5' và phosphate alpha) và 2 liên kết phosphoanhydride cao năng (giữa phosphate alpha-beta và beta-gamma)."],["Chất nào sau đây giữ vai trò là 'chất truyền thông tin thứ hai' (second messenger) quan trọng trong tế bào?",["dATP","AMP vòng (cAMP)","UDP-glucose","FAD+"],1,"Lời giải: AMP vòng (Adenosine 3',5'-cyclic monophosphate - cAMP) và cGMP là các nucleotide đóng vai trò chất truyền thông tin thứ hai trong truyền tin tế bào."],["Các coenzyme trao đổi electron quan trọng như NAD+, NADP+, FAD+ có thành phần cấu tạo chứa nucleotide nào?",["AMP (Adenylate)","GMP (Guanylate)","UMP (Uridylate)","CMP (Cytidylate)"],0,"Lời giải: NAD+, NADP+, FAD+ và Coenzyme A đều chứa gốc Adenosine monophosphate (AMP) trong cấu trúc phức hợp."],["Chất trung gian được hoạt hóa UDP-glucose tham gia vào quá trình sinh tổng hợp chất nào trong cơ thể?",["Cholesterol","Glycogen","Protein","Acid béo"],1,"Lời giải: UDP-glucose là dạng glucose hoạt hóa đóng vai trò chất cho gốc glucosyl trong tổng hợp Glycogen."],["Đơn vị cấu tạo nên chuỗi polymer Acid Nucleic (DNA, RNA) liên kết với nhau thông qua loại liên kết nào?",["Liên kết Peptide 3',5'","Liên kết Phosphodiester 3',5'","Liên kết Glycoside 2',5'","Liên kết Hydrogen 3',5'"],1,"Lời giải: Các nucleotide đơn phân nối với nhau liên tục bằng liên kết 3',5'-phosphodiester giữa nhóm 3'-OH của đường trước và nhóm 5'-phosphate của đường sau."],["Trình tự các nucleotide trong một chuỗi đơn acid nucleic được viết theo chiều quy ước chuẩn là:",["Chiều từ đầu 3' đến đầu 5'","Chiều từ đầu 5' đến đầu 3'","Chiều tùy thuộc vào loại tế bào","Chiều từ C2' đến C4'"],1,"Lời giải: Theo quy ước quốc tế, chuỗi polynucleotide luôn được viết và đọc theo chiều từ đầu 5' (mang nhóm phosphate tự do) đến đầu 3' (mang nhóm -OH tự do)."],["Mô hình cấu trúc xoắn đôi DNA do James Watson và Francis Crick phát minh vào năm nào?",["1945","1953","1968","1975"],1,"Lời giải: Cấu trúc xoắn đôi DNA được Watson và Crick công bố trên tạp chí Nature vào năm 1953 (giải Nobel năm 1962)."],["Đặc điểm nào sau đây ĐÚNG với mô hình xoắn đôi DNA dạng B tiêu chuẩn của Watson-Crick?",["Hai chuỗi đối song song, xoắn theo chiều trái","Khung đường-phosphate nằm bên trong, các base nitơ thò ra ngoài","Hai chuỗi đối song song, xoắn theo chiều phải","Các base nitơ liên kết với nhau bằng liên kết cộng hóa trị"],2,"Lời giải: DNA dạng B gồm 2 chuỗi polynucleotide đối song song (1 chuỗi 5'->3', 1 chuỗi 3'->5') xoắn quanh 1 trục chung theo chiều phải."],["Trong phân tử DNA xoắn đôi, vị trí của khung đường-phosphate và các base nitơ được phân bố như thế nào?",["Khung đường-phosphate nằm bên trong (kỵ nước), base nitơ nằm bên ngoài (ưa nước)","Khung đường-phosphate nằm bên ngoài (ưa nước), base nitơ nằm bên trong (kỵ nước)","Cả hai cùng nằm xen kẽ bên ngoài trục xoắn","Cả hai cùng nằm xếp chồng ở lõi trung tâm"],1,"Lời giải: Khung tích điện âm tích cực gồm đường pentose và phosphate tích điện nằm ở phía ngoài tiếp xúc với nước, các nhân base nitơ kỵ nước xếp chồng ở phía trong."],["Nguyên tắc bổ sung giữa các base nitơ trên hai mạch đơn của DNA được thể hiện như thế nào?",["A liên kết với T bằng 3 liên kết hydrogen; G liên kết với C bằng 2 liên kết hydrogen","A liên kết với T bằng 2 liên kết hydrogen; G liên kết với C bằng 3 liên kết hydrogen","A liên kết với G bằng 2 liên kết hydrogen; T liên kết với C bằng 3 liên kết hydrogen","A liên kết với U bằng 2 liên kết hydrogen; G liên kết với C bằng 3 liên kết hydrogen"],1,"Lời giải: Theo nguyên tắc bổ sung Watson-Crick: A liên kết với T bằng 2 liên kết H (A=T); G liên kết với C bằng 3 liên kết H (G≡C)."],["Quy tắc Chargaff khẳng định mối quan hệ nào giữa các base nitơ trong phân tử DNA hai mạch?",["Tỷ lệ %A = %G và %T = %C","Số lượng A = T và G = C, do đó A + G = T + C","Tỷ lệ (A+T)/(G+C) luôn bằng 1 ở mọi loài","Số lượng A = C và G = T"],1,"Lời giải: Quy tắc Chargaff: Trong DNA sợi đôi, số nucleotide Adenine bằng Thymine (A=T) và Guanine bằng Cytosine (G=C), dẫn đến tổng Purine bằng tổng Pyrimidine (A+G = T+C)."],["Một mẫu DNA có tỷ lệ nucleotide loại Guanine (G) là 30%. Tỷ lệ % nucleotide loại Adenine (A) của mẫu DNA này là bao nhiêu?",["30%","20%","40%","15%"],1,"Lời giải: Vì %G = %C = 30% => %G + %C = 60%. Do đó %A + %T = 100% - 60% = 40%. Vì %A = %T => %A = 20%."],["Trong xoắn đôi DNA dạng B, đường kính của phân tử xoắn và chiều dài của một chu kỳ xoắn (vòng xoắn) lần lượt là bao nhiêu?",["Đường kính ~26 Å, chu kỳ xoắn ~28 Å","Đường kính ~20 Å, chu kỳ xoắn ~34 Å","Đường kính ~18 Å, chu kỳ xoắn ~45 Å","Đường kính ~20 Å, chu kỳ xoắn ~12 Å"],1,"Lời giải: DNA dạng B có đường kính khoảng 20 Å (2 nm), mỗi vòng xoắn gồm ~10.5 cặp base dài 34 Å (3.4 nm), khoảng cách giữa 2 cặp base kế tiếp là 3.4 Å."],["Dạng cấu trúc 3 chiều nào của DNA có đặc điểm xoắn theo chiều TRÁI (left-handed helix)?",["Dạng A-DNA","Dạng B-DNA","Dạng Z-DNA","Dạng C-DNA"],2,"Lời giải: Z-DNA là dạng cấu trúc xoắn kép theo chiều trái (khung đường-phosphate ngoằn ngoèo hình ziczac), đường kính thu hẹp ~18 Å và chứa 12 cặp base/vòng."],["Trình tự acid nucleic đối ứng hai lần (Palindromic sequence) trên một mạch đơn có thể tự bổ sung tạo nên cấu trúc gì?",["Cấu trúc kẹp tóc (Hairpin)","Cấu trúc hình Z-DNA","Cấu trúc sợi đôi thẳng","Cấu trúc cỏ 3 lá"],0,"Lời giải: Trình tự Palindrome khi xuất hiện trên 1 mạch đơn có thể tự gập lại bắt cặp bổ sung tạo cấu trúc kẹp tóc (Hairpin). Khi xảy ra trên cả 2 mạch của DNA sợi đôi tạo cấu trúc chữ thập (Cruciform)."],["Sự hình thành các trình tự cấu trúc ít gặp (kẹp tóc, chữ thập) có vai trò sinh học quan trọng trong quá trình nào?",["Khởi phát hoặc điều hòa nhân đôi, tái tổ hợp và sao chép DNA","Tăng trọng lượng phân tử của tế bào","Khóa vĩnh viễn sự phiên mã của gen","Phân hủy các base nitơ thừa"],0,"Lời giải: Các cấu trúc đặc biệt như Hairpin, Cruciform đóng vai trò tín hiệu nhận biết cho các protein điều hòa trong quá trình tái bản (nhân đôi), sao chép (phiên mã) và tái tổ hợp DNA."],["Trong quá trình truyền thông tin di truyền, chuỗi DNA được dùng làm khuôn mẫu để tổng hợp nên phân tử mRNA được gọi là:",["Chuỗi mã hóa (Coding strand)","Chuỗi khuôn mẫu (Template strand)","Chuỗi bổ sung (Complementary strand)","Chuỗi intron"],1,"Lời giải: Trong 2 mạch của DNA, chỉ có 1 mạch được RNA polymerase sử dụng làm khuôn mẫu phiên mã, gọi là chuỗi khuôn mẫu (template strand)."],["Điểm khác biệt căn bản về thành phần hóa học giữa phân tử RNA và DNA là gì?",["RNA chứa đường D-Ribose và base Uracil; DNA chứa đường 2'-Deoxyribose và base Thymine","RNA chứa đường Deoxyribose và base Thymine; DNA chứa đường Ribose và base Uracil","RNA chứa acid phosphoric còn DNA thì không có","RNA chứa base Cytosine còn DNA chứa base Guanine"],0,"Lời giải: Hai khác biệt hóa học cốt lõi: RNA chứa đường D-ribose và base Uracil (U), trong khi DNA chứa đường 2'-deoxyribose và base Thymine (T)."],["Phân tử RNA thông tin (mRNA) ở tế bào Eukaryote sau khi mới được phiên mã (mRNA sơ khai) có đặc điểm nào?",["Đã loại bỏ hoàn toàn các đoạn exon","Chứa cả các đoạn Exon (mã hóa) và Intron (không mã hóa)","Có ngay cấu trúc cỏ 3 lá","Được dịch mã ngay trong nhân tế bào"],1,"Lời giải: mRNA sơ khai (pre-mRNA) ở nhân Eukaryote chứa các vùng mang thông tin mã hóa (exon) xen kẽ các vùng không mã hóa (intron)."],["Quá trình hoàn thiện mRNA sơ khai ở tế bào Eukaryote để tạo thành mRNA trưởng thành bao gồm các bước nào?",["Gắn mũ Cap 5', gắn đuôi Poly(A) 3' và cắt bỏ các đoạn Intron (splicing)","Cắt bỏ các đoạn Exon và nối các đoạn Intron lại với nhau","Biến đổi đường Ribose thành Deoxyribose","Thêm base Thymine vào đầu 3'"],0,"Lời giải: Quá trình biến đổi sau phiên mã ở Eukaryote gồm: Gắn m7G-cap ở đầu 5', thêm đuôi Poly(A) ở đầu 3' và cắt bỏ các intron, nối các exon (splicing)."],["Loại RNA nào chiếm tỷ lệ trọng lượng lớn nhất trong tổng số RNA của tế bào (thường chiếm >80%)?",["mRNA","tRNA","rRNA","snRNA"],2,"Lời giải: RNA ribosome (rRNA) chiếm tỷ trọng lớn nhất (~80-85% tổng lượng RNA tế bào) vì nó cấu tạo nên bộ máy tổng hợp protein (ribosome)."],["Chức năng sinh học chính của phân tử RNA vận chuyển (tRNA) là gì?",["Làm khuôn mẫu trực tiếp cho quá trình dịch mã","Cấu tạo nên tiểu đơn vị bé của ribosome","Đọc mã di truyền trên mRNA và vận chuyển amino acid tương ứng đến ribosome","Cắt bỏ các đoạn intron trong quá trình cắt nối RNA"],2,"Lời giải: tRNA có chức năng vận chuyển các amino acid đã được hoạt hóa tới ribosome và giải mã các bộ ba codon trên mRNA nhờ bộ ba đối mã (anticodon)."],["Tất cả các phân tử tRNA trưởng thành đều mang trình tự bộ ba nucleotide cố định nào ở đầu 3'-OH nơi gắn amino acid?",["5'-AUG-3'","5'-CCA-3'","5'-UAA-3'","5'-GGC-3'"],1,"Lời giải: Tất cả các tRNA đều có đầu 3'-OH tận cùng mang trình tự CCA (đoạn nhánh tiếp nhận amino acid)."],["Đặc điểm nào sau đây giải thích vì sao DNA được coi là cơ sở vật chất di truyền chính thức ở cấp độ phân tử thay vì RNA?",["DNA tồn tại suốt theo đời sống tế bào, bền vững hơn và có cơ chế sửa chữa; trong khi RNA bị phân hủy sau khi sử dụng","RNA không có khả năng nhân đôi","DNA chứa Uracil có tính bền vững hóa học cao hơn","RNA có kích thước phân tử quá lớn không thể chui qua màng nhân"],0,"Lời giải: DNA bền vững hóa học hơn (do đường 2'-deoxyribose ít bị thủy phân kiềm và cấu trúc xoắn kép) và tồn tại lâu dài, là kho lưu trữ thông tin di truyền vĩnh viễn; RNA chỉ là bản sao trung gian ngắn hạn."],["Các base hiếm xuất hiện trong phân tử DNA và RNA thường là sản phẩm của phản ứng biến đổi hóa học nào?",["Thủy phân","Methyl hóa các base phổ biến","Oxy hóa cắt vòng","Khử nhóm phosphate"],1,"Lời giải: Các base hiếm (như 5-methylcytosine, N6-methyladenine...) thường được tạo ra do sự methyl hóa các base tiêu chuẩn, có vai trò điều hòa biểu hiện gen và bảo vệ DNA."],["Nucleosidase (hoặc nucleoside phosphorylase) là enzyme thủy phân liên kết nào trong cấu trúc acid nucleic?",["Liên kết Phosphodiester","Liên kết β,N-glycoside giữa base nitơ và đường pentose","Liên kết Hydrogen giữa hai mạch","Liên kết Anhydride acid"],1,"Lời giải: Nucleosidase phân cắt liên kết N-glycoside giải phóng base nitơ tự do và đường pentose (hoặc pentose-1-phosphate)."],["Enzyme Nuclease (như Ribonuclease, Deoxyribonuclease) thủy phân loại liên kết nào?",["Liên kết β,N-glycoside","Liên kết Phosphodiester giữa các nucleotide","Liên kết Peptide","Liên kết Hydrogen"],1,"Lời giải: Nuclease (phosphoesterase) xúc tác phản ứng thủy phân các liên kết phosphodiester trong chuỗi polynucleotide."],["Base nitơ nào sau đây là dẫn xuất của nhân Pyrimidine?",["Adenine","Guanine","Cytosine","Hypoxanthine"],2,"Lời giải: Cytosine, Thymine, Uracil thuộc nhóm Pyrimidine (vòng đơn 6 cạnh). Adenine, Guanine, Hypoxanthine, Xanthine thuộc nhóm Purine (vòng đôi)."],["Tính chất biến tính (denaturation) của phân tử DNA xảy ra khi có sự phá hủy liên kết nào?",["Liên kết phosphodiester","Liên kết Hydrogen giữa hai mạch","Liên kết N-glycoside","Liên kết đồng hóa trị"],1,"Lời giải: Sự biến tính DNA (tách 2 mạch đơn) do nhiệt độ cao hoặc pH kiềm làm đứt các liên kết hydrogen giữa các cặp base bổ sung mà không làm đứt liên kết phosphodiester."],["Nhiệt độ nóng chảy Tm (Melting temperature) của DNA là nhiệt độ tại đó:",["100% phân tử DNA bị phân hủy thành nucleotide đơn phân","50% số phân tử DNA bị tách thành hai mạch đơn","DNA bắt đầu kết tủa","Các liên kết phosphodiester bị đứt hoàn toàn"],1,"Lời giải: Tm là nhiệt độ tại đó 50% cấu trúc xoắn kép DNA bị biến tính thành chuỗi đơn. DNA giàu cặp G-C có Tm cao hơn do có 3 liên kết H."],["Phân tử DNA có tỷ lệ cặp G-C càng cao thì nhiệt độ nóng chảy (Tm) sẽ như thế nào?",["Càng thấp do cặp G-C dễ bị đứt","Càng cao do cặp G-C có 3 liên kết hydrogen bền vững hơn","Không thay đổi vì Tm chỉ phụ thuộc vào chiều dài","Bằng 0 độ C"],1,"Lời giải: Cặp G≡C có 3 liên kết H nên cần nhiều năng lượng nhiệt hơn để phá vỡ so với cặp A=T (2 liên kết H). Tỷ lệ G-C càng cao thì Tm càng cao."],["Trong tế bào Eukaryote, phân tử DNA bộ gen (genomic DNA) liên kết với nhóm protein kiềm nào để cuộn xoắn tạo cấu trúc Chromatin?",["Albumin","Histone","Globulin","Collagen"],1,"Lời giải: DNA liên kết với các protein Histone giàu Lysine và Arginine (mang điện tích dương) để đóng gói thành các đơn vị nucleosome và nhiễm sắc chất."],["Mã di truyền trên phân tử mRNA được đọc theo các bộ ba nucleotide nối tiếp nhau, mỗi bộ ba được gọi là một:",["Anticodon","Codon","Exon","Cistron"],1,"Lời giải: Mỗi bộ ba nucleotide trên mRNA mã hóa cho 1 amino acid được gọi là một mã bộ ba (Codon). Bộ ba đối mã trên tRNA gọi là Anticodon."],["Số lượng mã bộ ba (Codon) tối đa có thể được tạo thành từ 4 loại base nitơ A, U, G, C trên mRNA là:",["16","32","64","20"],2,"Lời giải: Số tổ hợp mã bộ ba là 4^3 = 64 codon (trong đó có 61 codon mã hóa cho 20 amino acid và 3 codon kết thúc UAA, UAG, UGA)."],["Codon nào sau đây vừa đóng vai trò là mã mở đầu (start codon) vừa mã hóa cho amino acid Methionine?",["5'-UAA-3'","5'-AUG-3'","5'-UAG-3'","5'-UGA-3'"],1,"Lời giải: 5'-AUG-3' là mã mở đầu phổ biến trên mRNA mã hóa cho Methionine (hoặc Formyl-methionine ở vi khuẩn)."],["Các bộ ba nào sau đây đóng vai trò là mã kết thúc (stop codon) dừng quá trình dịch mã?",["AUG, UAA, UAG","UAA, UAG, UGA","UAA, UAC, UGA","UGA, UGG, UAA"],1,"Lời giải: 3 mã kết thúc không mã hóa cho amino acid nào là UAA (ochre), UAG (amber) và UGA (opal)."],["Khái niệm 'tính suy biến' (degeneracy) của mã di truyền có nghĩa là:",["Một codon có thể mã hóa cho nhiều amino acid khác nhau","Nhiều codon khác nhau cùng mã hóa cho một amino acid","Mã di truyền thay đổi tùy theo từng loài sinh vật","Mã di truyền bị thoái hóa theo thời gian"],1,"Lời giải: Tính suy biến (dư thừa) của mã di truyền có nghĩa là một amino acid có thể được mã hóa bởi nhiều codon khác nhau (ví dụ Leucine có đến 6 codon)."],["Thành phần nào cấu tạo nên tiểu đơn vị nhỏ và tiểu đơn vị lớn của Ribosome?",["rRNA và các Protein ribosome","mRNA và tRNA","DNA và Histone","Lipid và Glycoprotein"],0,"Lời giải: Ribosome là một phức hợp ribonucleoprotein gồm các phân tử rRNA đóng vai trò khung cấu trúc/xúc tác và hàng chục loại protein ribosome."],["Quá trình thoái hóa acid nucleic ở đường tiêu hóa và tế bào bắt đầu bằng sự phân cắt liên kết phosphodiester nhờ enzyme nào?",["Nuclease (phosphoesterase)","Nucleotidase","Nucleosidase","Xanthine oxidase"],0,"Lời giải: Quá trình thủy phân acid nucleic mở đầu bằng việc enzyme Nuclease (như Ribonuclease, Deoxyribonuclease tụy) phân cắt liên kết phosphodiester tạo các nucleotide đơn phân."],["Enzyme 5'-Nucleotidase (phosphatase) xúc tác cho phản ứng thoái hóa nào sau đây?",["Cắt acid nucleic thành nucleotide","Cắt nhóm phosphate của Nucleotide để tạo thành Nucleoside","Cắt liên kết N-glycoside của nucleoside","Oxy hóa Xanthine thành Acid Uric"],1,"Lời giải: 5'-Nucleotidase là một phosphatase giúp loại bỏ nhóm phosphate từ nucleotide để tạo thành nucleoside tương ứng."],["Sản phẩm thoái hóa cuối cùng của nhân Purine nucleotide ở người và các loài linh trưởng bậc cao là gì?",["Urea","Allantoin","Acid Uric","β-Alanine"],2,"Lời giải: Ở người và linh trưởng bậc cao, do thiếu enzyme Uricase, sản phẩm thoái hóa cuối cùng của các purine nucleotide (AMP, GMP) là Acid Uric."],["Ở hầu hết các động vật có vú khác (trừ con người và linh trưởng bậc cao), Acid Uric tiếp tục được chuyển hóa thành chất nào dễ tan trong nước nhờ enzyme Uricase?",["Allantoin","Xanthine","Hypoxanthine","β-Aminoisobutyrate"],0,"Lời giải: Ở các loài động vật có vú khác, enzyme Uricase (Urate oxidase) oxy hóa Acid Uric thành Allantoin - một chất dễ tan trong nước và dễ đào thải qua nước tiểu."],["Trong con đường thoái hóa Purine, Adenosine được biến đổi thành Inosine nhờ xúc tác của enzyme nào?",["Guanine deaminase","Adenosine deaminase (ADA)","Xanthine oxidase","Adenylate kinase"],1,"Lời giải: Adenosine trải qua phản ứng khử amin nhờ enzyme Adenosine Deaminase (ADA) để tạo thành Inosine."],["Sự thiếu hụt bẩm sinh enzyme Adenosine Deaminase (ADA) dẫn đến sự tích tụ chất nào gây độc cho tế bào lympho T và B, gây ra bệnh lý gì?",["Tích tụ Acid Uric gây bệnh Gout cấp","Tích tụ dATP gây bệnh Suy giảm miễn dịch kết hợp nặng (SCID)","Tích tụ Orotate gây bệnh Acid orotic niệu","Tích tụ PRPP gây hội chứng Lesch-Nyhan"],1,"Lời giải: Thiếu ADA làm tích tụ dATP trong tế bào, kìm hãm mạnh enzyme Ribonucleotide Reductase, ngăn cản sự tổng hợp DNA làm suy giảm nghiêm trọng lympho T và B gây bệnh SCID."],["Enzyme Xanthine Oxidase xúc tác cho phản ứng thoái hóa nào sau đây?",["Chuyển Hypoxanthine thành Xanthine và chuyển Xanthine thành Acid Uric","Chuyển Adenosine thành Inosine","Chuyển Guanine thành Xanthine","Chuyển Acid Uric thành Allantoin"],0,"Lời giải: Xanthine Oxidase (XO) xúc tác cả 2 bước oxy hóa liên tiếp: Hypoxanthine -> Xanthine -> Acid Uric."],["Thuốc Allopurinol được sử dụng phổ biến trong điều trị bệnh Gout nhờ cơ chế tác dụng nào?",["Tăng cường hoạt tính enzyme Uricase để phân hủy acid uric","Ức chế enzyme Xanthine Oxidase làm giảm sản xuất acid uric","Kích thích thận bài tiết acid uric qua nước tiểu","Ức chế sự hấp thu purine ở ruột"],1,"Lời giải: Allopurinol có cấu trúc tương tự Hypoxanthine, bị Xanthine Oxidase chuyển thành Alloxanthine gắn chặt và ức chế cạnh tranh bất thuận nghịch enzyme này, làm giảm tổng hợp Acid Uric."],["Bệnh Gout xảy ra do hiện tượng nào sau đây?",["Tăng nồng độ Urea máu kéo dài","Tăng nồng độ Acid Uric máu làm lắng đọng tinh thể muối Natri Urat ở các khớp và thận","Thiếu hụt vitamin B12 làm tích tụ Succinyl-CoA","Tích tụ β-Alanine ở cơ vân"],1,"Lời giải: Khi acid uric máu tăng cao vượt ngưỡng hòa tan (>420 μmol/L ở nam), tinh thể Urat natri ít tan sẽ lắng đọng tại màng hoạt dịch khớp gây viêm khớp Gout và ở thận gây sỏi urat."],["Các sản phẩm thoái hóa cuối cùng của nhân Pyrimidine (Cytosine, Uracil, Thymine) có đặc điểm gì nổi bật?",["Là các hợp chất ít tan dễ gây sỏi thận","Là các hợp chất dễ tan trong nước gồm CO2, NH3, β-Alanine và β-Aminoisobutyrate","Đều chuyển hóa thành Acid Uric","Đều bị kìm hãm bởi Allopurinol"],1,"Lời giải: Thoái hóa vòng Pyrimidine mở vòng tạo các sản phẩm tan tốt trong nước: CO2, NH3, β-Alanine (từ C, U) và β-Aminoisobutyrate (từ T)."],["Sản phẩm thoái hóa β-Aminoisobutyrate của Thymine được tiếp tục chuyển hóa thành chất trung gian nào đi vào chu trình Krebs?",["Oxaloacetate","Succinyl-CoA","Alpha-Ketoglutarate","Acetyl-CoA"],1,"Lời giải: β-Aminoisobutyrate trải qua phản ứng trao đổi amin và biến đổi cần Vitamin B12 để tạo thành Methylmalonyl-CoA -> Succinyl-CoA đi vào chu trình Krebs."],["Trong cơ thể sinh vật có mấy con đường chính để sinh tổng hợp các Nucleotide?",["1 con đường độc nhất","2 con đường: Tổng hợp mới (De novo) và Tận dụng (Salvage)","3 con đường: Qua Krebs, Qua HMP, Qua Chu trình Urea","4 con đường riêng biệt"],1,"Lời giải: Tế bào tổng hợp nucleotide qua 2 con đường: De novo pathway (tổng hợp mới từ các tiền chất đơn giản) và Salvage pathway (tái sử dụng base nitơ/nucleoside giải phóng từ thoái hóa)."],["Hợp chất cao năng đóng vai trò là chất trung gian mấu chốt khống chế cả 2 con đường tổng hợp Purine và Pyrimidine là gì?",["Ribose-5-Phosphate","5-Phosphoribosyl-1-pyrophosphate (PRPP)","Carbamoyl phosphate","IMP"],1,"Lời giải: PRPP (5-phosphoribosyl-1-pyrophosphate) là dạng hoạt hóa của đường ribose-5-P cung cấp gốc ribose-P cho cả tổng hợp De novo và Salvage của Purine lẫn Pyrimidine."],["Enzyme xúc tác cho phản ứng tổng hợp PRPP từ Ribose-5-Phosphate và ATP là:",["PRPP Synthetase","Glutamine-PRPP amidotransferase","PRPP Kinase","Ribonucleotide Reductase"],0,"Lời giải: PRPP Synthetase (cần Mg2+) xúc tác chuyển nhóm pyrophosphate từ ATP sang C1 của Ribose-5-P tạo PRPP."],["Con đường tổng hợp MỚI (De novo) nhân Purine nucleotide có đặc điểm khởi đầu nào sau đây?",["Vòng Purine được tổng hợp hoàn chỉnh trước rồi mới gắn vào PRPP","Vòng Purine được xây dựng từng nguyên tử ngay trên nền khuôn PRPP","Base Adenine tự do gắn trực tiếp vào PRPP","Chỉ xảy ra ở ti thể tế bào cơ"],1,"Lời giải: Ở tổng hợp Purine de novo, các nguyên tử của vòng purine được lắp ráp từng bước trực tiếp lên khung khung PRPP (tạo thành 5-phosphoribosyl-1-amine đầu tiên)."],["Phản ứng mở đầu được coi là bước khống chế (committed step) của con đường tổng hợp MỚI Purine nucleotide do enzyme nào xúc tác?",["PRPP Synthetase","Glutamine-PRPP amidotransferase","Adenylosuccinate synthetase","IMP dehydrogenase"],1,"Lời giải: Phản ứng chuyển nhóm amide từ Glutamine sang PRPP thay thế nhóm pyrophosphate tạo 5-phosphoribosyl-1-amine do Glutamine-PRPP amidotransferase xúc tác là bước khống chế đầu tiên."],["Chất trung gian nucleotide đầu tiên có vòng Purine hoàn chỉnh được tạo ra trong con đường tổng hợp De novo là:",["AMP","GMP","IMP (Inosinate)","XMP"],2,"Lời giải: IMP (Inosine monophosphate - chứa base Hypoxanthine) là sản phẩm nucleotide purine hoàn chỉnh đầu tiên được tạo ra từ chuỗi phản ứng de novo."],["Nguồn gốc các nguyên tử trong vòng Purine xuất phát từ các tiền chất nào sau đây?",["N1 từ Aspartate; C2, C8 từ Formate; N3, N9 từ Amide của Glutamine; C4, C5, N7 từ Glycine; C6 từ CO2","Toàn bộ từ Alanine và Urea","C1 từ Glucose; N từ Ammonia tự do","N1 từ Glutamine; C từ Acetyl-CoA"],0,"Lời giải: Vòng Purine được lắp ghép từ: Glycine (C4,C5,N7), Glutamine (N3,N9), Aspartate (N1), N10-Formyl-TH4 (C2,C8) và CO2/HCO3- (C6)."],["Trong sự phân nhánh từ IMP để tạo thành AMP và GMP, năng lượng tiêu tốn cho phản ứng tạo AMP được cung cấp bởi chất nào?",["ATP","GTP","CTP","UTP"],1,"Lời giải: Tổng hợp AMP từ IMP (qua Adenylosuccinate) sử dụng năng lượng từ GTP. Ngược lại, tổng hợp GMP từ IMP (qua XMP) sử dụng năng lượng từ ATP (sự điều hòa chéo)."],["Sự khác biệt cốt lõi giữa con đường tổng hợp De novo của PYRIMIDINE so với PURINE là gì?",["Pyrimidine được gắn PRPP trước rồi mới đóng vòng","Vòng Pyrimidine được tổng hợp hoàn chỉnh (tạo Orotate) trước rồi mới gắn với PRPP","Pyrimidine không cần đến PRPP","Pyrimidine chỉ được tổng hợp từ base tái sử dụng"],1,"Lời giải: Khác với Purine xây vòng trên PRPP, tổng hợp Pyrimidine de novo đóng vòng đĩa Pyrimidine trước (tạo Orotate) rồi mới gắn Orotate vào PRPP để tạo OMP."],["Enzyme xúc tác cho phản ứng đầu tiên tổng hợp Carbamoyl Phosphate trong bào tương phục vụ cho tổng hợp Pyrimidine là:",["Carbamoyl Phosphate Synthetase I (CPS-I)","Carbamoyl Phosphate Synthetase II (CPS-II)","Aspartate transcarbamoylase (ATCase)","PRPP Synthetase"],1,"Lời giải: CPS-II ở bào tương tổng hợp Carbamoyl Phosphate từ Glutamine + CO2 + 2 ATP cho pyrimidine. CPS-I ở ti thể sử dụng NH3 tự do phục vụ chu trình urea."],["Tiền chất cung cấp phần lớn các nguyên tử C4, C5, C6 và N1 cho vòng Pyrimidine là acid amin nào?",["Glutamine","Glycine","Aspartate","Alanine"],2,"Lời giải: Phân tử Aspartate gắn với Carbamoyl phosphate đóng góp tới 4 nguyên tử (N1, C4, C5, C6) cho khung vòng 6 cạnh Pyrimidine."],["Nucleotide pyrimidine đầu tiên được tạo thành trong con đường de novo sau khi decarboxyl hóa Orotidylate (OMP) là:",["CMP","UMP (Uridylate)","dTMP","CTP"],1,"Lời giải: Orotidylate (OMP) bị loại nhóm CO2 bởi Orotidylate decarboxylase để tạo thành UMP (Uridine monophosphate)."],["Cytidine triphosphate (CTP) được tổng hợp trực tiếp từ tiền chất nucleotide nào?",["UMP","UTP (nhờ enzyme CTP Synthetase + Glutamine + ATP)","CMP","dUMP"],1,"Lời giải: UTP được biến đổi thành CTP nhờ CTP Synthetase, nhận nhóm amino từ Glutamine và năng lượng từ ATP."],["Quá trình khử các Ribonucleotide (NDP) thành Deoxyribonucleotide (dNDP) ở vị trí C2' của đường ribose được xúc tác bởi phức hợp enzyme nào?",["Ribonucleotide Reductase","PRPP Synthetase","Thymidylate Synthase","Adenylate Cyclase"],0,"Lời giải: Ribonucleotide Reductase xúc tác khử trực tiếp nhóm 2'-OH của các Ribonucleoside diphosphate (ADP, GDP, CDP, UDP) thành 2'-deoxyribonucleoside diphosphate tương ứng."],["Protein nào cung cấp nguyên tử Hydro (H) trực tiếp để phục hồi trạng thái khử cho Ribonucleotide Reductase trong quá trình tạo Deoxyribonucleotide?",["Glutathione","Thioredoxin (nhờ Thioredoxin reductase và NADPH)","Cytochrome c","Hemoglobin"],1,"Lời giải: Thioredoxin chứa nhóm -SH hoạt động chuyển H khử cho Ribonucleotide Reductase, sau đó Thioredoxin oxidized được tái sinh nhờ Thioredoxin Reductase dùng NADPH."],["Tổng hợp Deoxythymidylate (dTMP) từ dUMP cần sự tham gia của enzyme Thymidylate Synthase và coenzyme chứa gốc 1-carbon nào?",["N5,N10-Methylene-Tetrahydrofolate (N5,N10-Methylene-FH4)","S-Adenosylmethionine (SAM)","Biotin","Pyridoxal phosphate"],0,"Lời giải: Thymidylate Synthase chuyển nhóm methyl từ N5,N10-Methylene-FH4 sang dUMP để tạo thành dTMP."],["Thuốc chống ung thư 5-Fluorouracil (5-FU) ức chế quá trình tổng hợp DNA của tế bào ung thư nhờ cơ chế nào?",["Ức chế enzyme PRPP Synthetase","Chuyển hóa thành FdUMP ức chế bất thuận nghịch enzyme Thymidylate Synthase","Phân hủy các base Guanine","Ức chế tổng hợp RNA ribosome"],1,"Lời giải: 5-FU vào tế bào biến thành FdUMP gắn chặt và ức chế bất thuận nghịch Thymidylate Synthase (chất ức chế tự sát), cạn kệt dTMP ngăn cản nhân đôi DNA."],["Con đường TẬN DỤNG (Salvage pathway) tái sử dụng các base Purine tự do (Adenine, Guanine, Hypoxanthine) kết hợp với chất nào để tạo nucleotide?",["Ribose-5-Phosphate","PRPP","Glucose-6-Phosphate","ATP tự do"],1,"Lời giải: Con đường tận dụng Purine gắn trực tiếp base tự do + PRPP -> Nucleotide monophosphate + PPi nhờ các enzyme phosphoribosyltransferase."],["Enzyme HGPRT (Hypoxanthine-Guanine phosphoribosyltransferase) xúc tác cho các phản ứng tái sử dụng nào?",["Hypoxanthine + PRPP -> IMP và Guanine + PRPP -> GMP","Adenine + PRPP -> AMP","Xanthine + ATP -> XMP","Cytosine + PRPP -> CMP"],0,"Lời giải: HGPRT xúc tác gắn PRPP với Hypoxanthine tạo IMP và gắn PRPP với Guanine tạo GMP. (Adenine gắn với PRPP nhờ enzyme APRT)."],["Hội chứng Lesch-Nyhan là bệnh di truyền lặn liên kết NST giới tính X xảy ra do thiếu hụt hoàn toàn enzyme nào?",["APRT","HGPRT","Adenosine Deaminase (ADA)","Xanthine Oxidase"],1,"Lời giải: Hội chứng Lesch-Nyhan do đột biến gen mã hóa HGPRT trên NST X làm mất hoàn toàn hoạt tính enzyme tái sử dụng purine này."],["Biểu hiện lâm sàng đặc trưng và vô cùng nghiêm trọng ở bệnh nhi nam mắc Hội chứng Lesch-Nyhan là gì?",["Rụng tóc và khô da","Tăng acid uric máu cực cao, tự gây thương tích (cắn môi, ngón tay), múa vờn, suy thận","Thiếu máu hồng cầu nhỏ hạt sắt","Viêm gan mạn tính"],1,"Lời giải: Do thiếu HGPRT, PRPP không được sử dụng bị tích tụ kích thích vọt con đường de novo làm tăng acid uric khủng kíp; bệnh nhi có hành vi tự tàn phá cơ thể (tự cắn môi, ngón tay), múa vờn và tổn thương thần kinh."],["Giải thích cơ chế gây tăng sản xuất Acid Uric nghiêm trọng trong Hội chứng Lesch-Nyhan:",["Thiếu HGPRT làm ngưng trệ con đường Salvage, nồng độ PRPP tăng cao kích thích vọt con đường tổng hợp De novo Purine","Xanthine Oxidase bị hoạt hóa gấp 100 lần","Thận tăng tái hấp thu urat","Tế bào tăng phân hủy protein"],0,"Lời giải: Thiếu HGPRT làm dư thừa PRPP (không bị tiêu thụ ở con đường salvage), đồng thời thiếu IMP/GMP (chất ức chế ngược), kích hoạt vọt bước hạn chế tốc độ Glutamine-PRPP amidotransferase trong con đường de novo."],["Bệnh lý Acid Orotique niệu (Orotic Aciduria) di truyền do thiếu hụt enzyme UMP Synthase dẫn đến sự tích tụ chất nào trong nước tiểu?",["Uric Acid","Orotate (Acid Orotic)","Xanthine","Carbamoyl phosphate"],1,"Lời giải: Thiếu hụt UMP Synthase (chứa 2 hoạt tính Orotate phosphoribosyltransferase & Orotidylate decarboxylase) làm Orotate không chuyển thành UMP được, bị đào thải nhiều qua nước tiểu."],["Điều trị bệnh nhân mắc Acid Orotique niệu bằng cách bổ sung hợp chất nào qua đường uống để vừa giảm đào thải orotate vừa cung cấp pyrimidine cho tế bào?",["Allopurinol","Uridine (hoặc Cytidine)","Thymine","Adenine"],1,"Lời giải: Cho uống Uridine giúp tế bào tạo UTP qua con đường salvage, UTP quay lại ức chế ngược enzyme CPS-II làm ngừng sản xuất quá mức Orotate."],["Con đường tái sử dụng Pyrimidine (Salvage pathway) ở động vật có vú biến đổi nucleoside Pyrimidine thành nucleotide nhờ các enzyme loại nào?",["Pyrimidine Kinase (như Uridine kinase, Thymidine kinase sử dụng ATP)","Phosphorylase","Deaminase","Oxidase"],0,"Lời giải: Tận dụng pyrimidine chủ yếu qua sự phosphoryl hóa các nucleoside (Uridine, Cytidine, Thymidine) nhờ các enzyme Kinase đặc hiệu sử dụng ATP."],["Sự chuyển đổi từ Nucleotide monophosphate (NMP) thành Nucleoside diphosphate (NDP) và tri-phosphate (NTP) trong tế bào do enzyme nào thực hiện?",["NMP Kinase và NDP Kinase đặc hiệu","PRPP Synthetase","Nuclease","Phosphatase"],0,"Lời giải: Các NMP Kinase đặc hiệu (như Adenylate kinase, Guanylate kinase) chuyển NMP + ATP ⇌ NDP + ADP. Sau đó NDP Kinase chuyển NDP + NTP_donor ⇌ NTP + NDP_donor."],["Phản ứng hồi lưu NMP Kinase quan trọng: AMP + ATP ⇌ 2 ADP được xúc tác bởi enzyme nào?",["Adenylate kinase (Myokinase)","Creatine kinase","Pyruvate kinase","Hexokinase"],0,"Lời giải: Adenylate kinase (Myokinase) duy trì sự cân bằng động giữa AMP, ADP và ATP trong cơ thể."],["Sự điều hòa con đường sinh tổng hợp MỚI của Purine nucleotide chịu sự ức chế ngược (feedback inhibition) chính bởi các sản phẩm nào?",["CTP và UTP","AMP, GMP và IMP","Acid Uric","PRPP"],1,"Lời giải: Nồng độ cao của các sản phẩm cuối AMP, GMP và IMP ức chế ngược cả PRPP Synthetase và Glutamine-PRPP amidotransferase."],["Enzyme khống chế chính của con đường tổng hợp Pyrimidine de novo ở tế bào động vật có vú là CPS-II bị ức chế ngược bởi chất nào và kích thích bởi chất nào?",["Bị ức chế bởi UTP; được kích thích bởi PRPP và ATP","Bị ức chế bởi CTP; được kích thích bởi UMP","Bị ức chế bởi Acid Uric; được kích thích bởi AMP","Bị ức chế bởi Allopurinol"],0,"Lời giải: CPS-II ở bào tương bị ức chế ngược bởi sản phẩm UTP, đồng thời được hoạt hóa bởi PRPP và ATP."],["Trường hợp nào sau đây gây TĂNG Acid Uric máu thứ phát?",["Bệnh nhân ung thư máu (Leukemia, Lymphoma) điều trị hóa chất làm tan rã tế bào hàng loạt","Uống nhiều nước lọc","Chế độ ăn thuần chay","Thiếu hụt vitamin C"],0,"Lời giải: Khi điều trị hóa trị ung thư, lượng lớn tế bào bị tiêu diệt giải phóng khối lượng khổng lồ Acid Nucleic thoái hóa thành Acid Uric gây hội chứng tan u (Tumor lysis syndrome) tăng Uric máu cấp."],["Xét nghiệm nồng độ Acid Uric máu bình thường ở người trưởng thành dao động trong khoảng nào?",["50 - 100 μmol/L","Nam: 180 - 420 μmol/L (3.0 - 7.0 mg/dL); Nữ: 150 - 360 μmol/L","800 - 1000 μmol/L","10 - 20 mmol/L"],1,"Lời giải: Nồng độ acid uric máu sinh lý bình thường ở Nam là 180-420 μmol/L, ở Nữ là 150-360 μmol/L."],["Vùng tổn thương khớp điển hình nhất trong đợt viêm khớp Gout cấp tính đầu tiên thường xuất hiện ở đâu?",["Khớp đốt bàn - ngón chân cái (ngón I)","Khớp vai","Khớp cột sống cổ","Khớp háng"],0,"Lời giải: Khớp bàn - ngón chân cái là vị trí xa tâm trí, nhiệt độ thấp hơn và áp lực vận động cao, là nơi đọng tinh thể muối urat điển hình nhất (>50% đợt Gout cấp)."],["Sự hình thành hạt Tophi ở bệnh nhân Gout mạn tính là do hiện tượng gì?",["Tích tụ canxi phosphat trong cơ","Lắng đọng u cục tinh thể Urat Natri dưới da, quanh khớp, vành tai","Viêm nhiễm vi khuẩn hình thành mủ","Phì đại xương"],1,"Lời giải: Hạt Tophi hình thành do sự lắng đọng mạn tính các khối tinh thể Urat Natri kích thước lớn bao bọc bởi mô sợi ở khớp, vành tai, sụn và phần mềm."],["Tác động của rượu bia làm trầm trọng thêm bệnh Gout theo cơ chế sinh hóa nào?",["Rượu gián tiếp tạo Lactate làm cạnh tranh đào thải Acid Uric ở ống thận, đồng thời chứa nhiều Purine","Rượu phân hủy trực tiếp Acid Uric thành chất độc","Rượu ức chế enzyme Xanthine Oxidase","Rượu làm tăng pH nước tiểu"],0,"Lời giải: Uống nhiều rượu làm tăng sản xuất Acid Lactic, lactate bài tiết qua ống thận sẽ cạnh tranh bài tiết với acid uric làm giảm đào thải acid uric, đồng thời đồ uống có cồn (nhất là bia) giàu purine."],["Enzyme Methotrexate (MTX) sử dụng trong hóa trị ung thư ức chế enzyme nào làm ngừng tổng hợp dTMP?",["Dihydrofolate Reductase (DHFR)","Thymidylate Synthase","PRPP Synthetase","Xanthine Oxidase"],0,"Lời giải: Methotrexate ức chế Dihydrofolate Reductase (DHFR), ngăn cản sự tái sinh Tetrahydrofolate (FH4), làm cạn kệt nguồn N5,N10-Methylene-FH4 cần cho tổng hợp dTMP và purine."],["Hợp chất Azaserine và Acivicin có tác dụng chống ung thư nhờ ức chế các phản ứng sử dụng acid amin nào trong tổng hợp Purine/Pyrimidine?",["Glutamine (chất đối kháng Glutamine)","Glycine","Aspartate","Alanine"],0,"Lời giải: Azaserine và Acivicin là các chất tương tự Glutamine (Glutamine antagonists) ức chế các enzyme chuyển nhóm amido N từ glutamine trong tổng hợp purine và pyrimidine."],["Quá trình thoái hóa Purine tạo ra oxy hoạt tính ROS (H2O2 và gốc Superoxide) ở bước phản ứng do enzyme nào xúc tác?",["Xanthine Oxidase","ADA","Guanine deaminase","Nucleosidase"],0,"Lời giải: Xanthine Oxidase sử dụng O2 làm chất nhận electron, trong quá trình oxy hóa Hypoxanthine/Xanthine sinh ra H2O2 và O2•- (ROS)."],["Nucleotide nào vừa là đơn vị cấu tạo RNA vừa là đồng yếu tố vận chuyển nhóm lipid trong tổng hợp Phospholipid màng?",["CDP (như CDP-diacylglycerol / CDP-choline)","UDP","GDP","ADP"],0,"Lời giải: Cytidine diphosphate (CDP) dạng hoạt hóa như CDP-choline, CDP-diacylglycerol là chất trung gian vận chuyển lipid trong tổng hợp phospholipid."],["Các nucleotide tri-phosphate (NTP) đi vào phản ứng trùng hợp tổng hợp DNA/RNA giải phóng nhóm nào?",["Pyrophosphate (PPi)","Monophosphate (Pi)","Base nitơ tự do","Ammonia"],0,"Lời giải: Khi dNTP hoặc NTP gắn vào chuỗi nucleic acid đang kéo dài, liên kết phosphoanhydride bị cắt giải phóng nhóm Pyrophosphate (PPi), PPi sau đó bị thủy phân thành 2 Pi giúp phản ứng diễn ra bất thuận nghịch."],["Nguồn gốc nguyên tử Cacbon C6 trong vòng Purine đến từ chất nào?",["CO2 (HCO3-)","Formate","Glycine","Glutamine"],0,"Lời giải: C6 của vòng Purine được gắn trực tiếp từ khí CO2 (HCO3-) thông qua phản ứng carboxyl hóa trong chuỗi de novo."],["Nguồn gốc nguyên tử Cacbon C2 và C8 trong vòng Purine đến từ chất nào?",["Gốc Formyl của N10-Formyl-Tetrahydrofolate (N10-Formyl-FH4)","Glycine","CO2","Aspartate"],0,"Lời giải: C2 và C8 của nhân purine được cung cấp bởi các gốc Formyl (-CHO) vận chuyển bởi coenzyme N10-Formyl-TH4."],["Toàn bộ khung 3 nguyên tử (C4, C5, N7) trong vòng Purine được đóng góp trọn vẹn từ phân tử acid amin nào?",["Glycine","Alanine","Serine","Glutamate"],0,"Lời giải: Một phân tử Glycine nguyên vẹn đi vào phản ứng nấc 2 gắn vào 5-phosphoribosyl-1-amine cung cấp toàn bộ 3 nguyên tử C4, C5 và N7."],["Nguyên tử Nitơ N1 trong vòng Purine được đóng góp bởi acid amin nào?",["Aspartate","Glutamine","Glycine","Lysine"],0,"Lời giải: Aspartate chuyển nhóm amino của mình để đóng góp nguyên tử Nitơ N1 cho vòng purine (giải phóng Fumarate)."],["Hai nguyên tử Nitơ N3 và N9 trong vòng Purine đến từ nguồn nào?",["Nhóm Amide (-NH2) của Glutamine","Ammonia tự do NH4+","Urea","Nitrat"],0,"Lời giải: Nhóm Amide N của Glutamine đóng góp 2 nguyên tử Nitơ ở vị trí N9 (bước 1) và N3 (bước 4) của vòng purine."],["Cơ quan nào trong cơ thể người là nơi diễn ra mạnh mẽ nhất quá trình tổng hợp MỚI (De novo) các Purine nucleotide?",["Gan","Não","Hồng cầu","Bạch cầu"],0,"Lời giải: Gan là cơ quan chính tổng hợp de novo các purine nucleotide để cung cấp cho các mô khác qua đường máu. Một số mô như Não và Tế bào máu phụ thuộc chủ yếu vào con đường Salvage."],["Tại sao tế bào não và hồng cầu lại đặc biệt nhạy cảm và tổn thương nghiêm trọng trong Hội chứng Lesch-Nyhan?",["Do các tế bào này có khả năng tổng hợp De novo rất yếu, phụ thuộc chủ yếu vào con đường Salvage (HGPRT)","Do các tế bào này chứa quá nhiều Xanthine Oxidase","Do acid uric làm hủy diệt vỏ myelin","Do thiếu hụt glucose"],0,"Lời giải: Não và tế bào máu có con đường tổng hợp de novo kém phát triển, sinh tồn dựa chính vào tái sử dụng purine qua HGPRT. Thiếu HGPRT khiến các mô này cạn kiệt nucleotide purine."],["Dạng tinh thể muối Urat natri đọng ở khớp trong bệnh Gout có hình dạng đặc trưng nào dưới kính hiển vi phân cực?",["Hình kim nhọn có tính lưỡng hình quang âm","Hình hình hộp chữ nhật","Hình cầu mịn","Hình đĩa dẹt"],0,"Lời giải: Dưới kính hiển vi ánh sáng phân cực, tinh thể Monosodium Urate (MSU) có dạng hình kim nhọn dài, phản xạ ánh sáng lưỡng cực âm rõ rệt."],["Phương pháp chẩn đoán xác định chuẩn vàng (gold standard) cho đợt viêm khớp Gout cấp tính là gì?",["Chọc hút dịch khớp tìm tinh thể Urat natri hình kim dưới kính hiển vi","Chỉ xét nghiệm acid uric máu","Chụp X-quang khớp","Đo tốc độ máu lắng"],0,"Lời giải: Tìm thấy tinh thể Monosodium Urate hình kim nằm trong hoặc ngoài tế bào trong dịch khớp dưới kính hiển vi phân cực là tiêu chuẩn vàng chẩn đoán Gout."],["Các thuốc hạ Acid Uric máu làm tăng bài tiết urat qua đường tiết niệu (Uricosuric agents) như Probenecid, Sulfinpyrazone có cơ chế tác dụng nào?",["Ức chế sự tái hấp thu Acid Uric tại ống thận gần","Ức chế Xanthine Oxidase","Phân hủy acid uric thành allantoin","Ức chế tổng hợp PRPP"],0,"Lời giải: Thuốc Uricosuric (Probenecid) ức chế kênh tái hấp thu urat URAT1 ở ống thận gần, làm tăng lượng acid uric đào thải ra nước tiểu."],["Enzyme Pegloticase hoặc Rasburicase là dạng tái tổ hợp của enzyme nào được dùng tiêm truyền để hạ nhanh acid uric máu ở bệnh nhân Gout kháng trị hoặc hội chứng tan u?",["Uricase (Urate oxidase)","Xanthine Oxidase","ADA","HGPRT"],0,"Lời giải: Pegloticase / Rasburicase là enzyme Uricase tái tổ hợp giúp chuyển hóa Acid Uric thành Allantoin tan tốt để đào thải nhanh."],["Phản ứng tổng hợp dTMP từ dUMP do Thymidylate Synthase xúc tác giải phóng chất nào làm tiêu tốn Tetrahydrofolate?",["Dihydrofolate (FH2)","Tetrahydrofolate (FH4)","Folic acid tự do","Methionine"],0,"Lời giải: Trong phản ứng tạo dTMP, N5,N10-methylene-FH4 vừa cho nhóm methyl vừa bị oxy hóa thành Dihydrofolate (FH2). Muốn tiếp tục phản ứng, FH2 phải nhờ DHFR khử lại thành FH4."],["Thuốc kháng sinh Trimethoprim và thuốc trị sốt rét Pyrimethamine kìm hãm sự phát triển của vi sinh vật nhờ ức chế chọn lọc enzyme DHFR của loài nào?",["Ức chế enzyme Dihydrofolate Reductase (DHFR) của vi khuẩn / ký sinh trùng trùng hợp","Ức chế DHFR của tế bào người","Ức chế vỏ tế bào vi khuẩn","Ức chế màng tế bào"],0,"Lời giải: Trimethoprim và Pyrimethamine gắn và ức chế chọn lọc enzyme DHFR của vi khuẩn và ký sinh trùng sốt rét với ái lực cao gấp hàng nghìn lần so với DHFR của người."],["Một bệnh nhân nam 50 tuổi vào viện vì đau dữ dội khớp ngón chân cái bên phải, khớp sưng nóng đỏ. Acid uric máu 520 μmol/L. Chẩn đoán sơ bộ nghĩ đến nhiều nhất là:",["Gout cấp","Viêm khớp dạng thấp","Thoái hóa khớp","Nhiễm trùng khớp"],0,"Lời giải: Cơn đau cấp tính dữ dội ở khớp bàn ngón chân cái kèm sưng nóng đỏ và tăng acid uric máu điển hình cho đợt Gout cấp."],["Khi điều trị cơn Gout CẤP tính, loại thuốc nào sau đây được ưu tiên sử dụng để giảm viêm đau cấp?",["Colchicine, NSAIDs hoặc Corticoid","Allopurinol ngay lập tức với liều cao","Kháng sinh amoxicillin","Vitamin C liều cao"],0,"Lời giải: Cơn Gout cấp ưu tiên điều trị chống viêm bằng Colchicine, NSAIDs hoặc Corticoid. Không nên bắt đầu Allopurinol ngay trong cơn cấp vì làm thay đổi đột ngột urat máu gây khởi phát cơn đau kéo dài."],["Chế độ ăn uống nào sau đây giúp hạn chế nguy cơ tái phát cơn Gout?",["Hạn chế thực phẩm giàu purine (nội tạng động vật, thịt đỏ, hải sản), kiêng rượu bia, uống đủ nước","Nhịn ăn hoàn toàn","Ăn nhiều thịt bò và uống bia","Uống ít nước"],0,"Lời giải: Giảm thực phẩm giàu purine (nội tạng, hải sản, thịt đỏ), kiêng rượu bia và uống nhiều nước (giúp tăng đào thải urat) là các biện pháp không dùng thuốc hàng đầu."],["Base Uracil và Thymine khác nhau ở nhóm thế nào?",["Thymine có thêm 1 nhóm Methyl (-CH3) ở vị trí C5 của vòng Pyrimidine","Uracil có thêm nhóm Amino (-NH2)","Thymine có ít hơn 1 nguyên tử Oxy","Uracil có cấu trúc vòng đôi"],0,"Lời giải: Thymine chính là 5-methyluracil (có gắn thêm nhóm -CH3 ở vị trí C5 của Uracil)."],["Nucleotide nào sau đây đóng vai trò là chất cho gốc Sulfat (active sulfate) trong các phản ứng liên hợp sulfat khử độc tại gan?",["PAPS (3'-Phosphoadenosine-5'-phosphosulfate)","SAM","UDPGA","ATP"],0,"Lời giải: PAPS (3'-phosphoadenosine-5'-phosphosulfate - sulfat hoạt hóa) chứa gốc adenine nucleotide là chất cho nhóm sulfate hóa giải độc."],["Sự tổng hợp dTMP từ dUMP bị ngưng trệ khi cơ thể thiếu hụt vitamin nào?",["Acid Folic (Vitamin B9) và Vitamin B12","Vitamin C","Vitamin A","Vitamin K"],0,"Lời giải: Thiếu Acid Folic (B9) và Vitamin B12 làm cạn kiệt THF (Tetrahydrofolate), kìm hãm tổng hợp dTMP và purine gây thiếu máu hồng cầu khổng lồ (Megaloblastic anemia)."],["Tóm tắt vai trò tổng quát của các Nucleotide trong cơ thể sống bao gồm:",["Đơn vị cấu tạo Acid Nucleic (DNA, RNA), vận chuyển năng lượng (ATP), cấu tạo coenzyme (NAD+, FAD, CoA), chất truyền tin nội bào (cAMP) và hoạt hóa chất trung gian","Chỉ làm nhiệm vụ dự trữ mỡ","Chỉ làm nhiệm vụ cấu tạo màng tế bào","Chỉ tham gia tạo sắc tố da"],0,"Lời giải: Nucleotide giữ vô số vai trò trung tâm: xây dựng vật chất di truyền, chuyển hóa năng lượng (ATP), cấu thành coenzyme, truyền tin nội bào (cAMP, cGMP) và hoạt hóa các chất trung gian (UDP-glucose, CDP-lipid)."]];
const HEMOGLOBIN=[["Hemoglobin (Hb) là loại protein tạp thuộc nhóm nào sau đây?",["Nucleoprotein","Chromoprotein (sắc tố protein)","Glycoprotein","Lipoprotein"],1,"Giải thích: Hemoglobin là một chromoprotein (protein tạp chứa nhóm ngoại có màu) với nhóm ngoại là Hem và phần protein thuần là Globin."],["Trọng lượng phân tử và đường kính trung bình của phân tử Hemoglobin ở người là:",["16.800 Da và 2.5 nm","32.000 Da và 4.0 nm","64.000 Da và 5.5 nm","128.000 Da và 8.0 nm"],2,"Giải thích: Phân tử Hemoglobin là một tetramer gồm 4 bán đơn vị, có khối lượng phân tử khoảng 64.000 Dalton và đường kính 5,5 nm."],["Tỷ lệ phần trăm về khối lượng của nhóm ngoại (Hem) và phần protein thuần (Globin) trong phân tử Hb là:",["4% Hem và 96% Globin","10% Hem và 90% Globin","15% Hem và 85% Globin","20% Hem và 80% Globin"],0,"Giải thích: Trong phân tử Hemoglobin, nhóm ngoại Hem chiếm khoảng 4% và phần protein thuần Globin chiếm khoảng 96% trọng lượng phân tử."],["Thành phần cấu tạo của một nhóm Hem hoàn chỉnh gồm có:",["Protoporphyrin IX kết hợp với Fe3+","Protoporphyrin IX kết hợp với Fe2+","Porphin kết hợp với Fe2+","Coproporphyrin III kết hợp với Fe2+"],1,"Giải thích: Hem được cấu tạo từ một vòng Protoporphyrin IX liên kết với ion sắt II (Fe2+) ở vị trí trung tâm."],["Khung cơ bản của Porphyrin (vòng Porphin) được cấu tạo từ 4 nhân pyrol nối với nhau bằng các cầu nối nào?",["Cầu nối Methylene (-CH2-)","Cầu nối Methenyl (=CH-)","Cầu nối Ether (-O-)","Cầu nối Disulfide (-S-S-)"],1,"Giải thích: Vòng Porphin được tạo thành từ 4 nhân pyrol liên kết với nhau bằng 4 cầu nối methenyl (=CH-)."],["Các nhóm thế trên vòng Protoporphyrin IX gắn vào 8 vị trí của 4 nhân pyrol gồm:",["4 Methyl (M), 2 Vinyl (V), 2 Propionic (P)","2 Methyl (M), 4 Vinyl (V), 2 Propionic (P)","4 Methyl (M), 4 Propionic (P)","2 Methyl (M), 2 Acetyl (A), 4 Propionic (P)"],0,"Giải thích: Protoporphyrin IX mang 8 nhóm thế: 4 nhóm Methyl (-CH3, M), 2 nhóm Vinyl (-CH=CH2, V) và 2 nhóm Propionic (-CH2-CH2-COOH, P)."],["Trật tự sắp xếp các nhóm thế trên 4 nhân pyrol của Protoporphyrin IX là:",["M, V, M, V, M, P, P, M","M, P, M, P, M, V, V, M","M, V, M, P, M, V, M, P","V, M, V, M, P, P, M, M"],0,"Giải thích: Protoporphyrin IX thuộc porphyrin nhóm III, có trật tự sắp xếp các nhóm thế trên 8 vị trí là M, V, M, V, M, P, P, M (đảo ngược ở vòng pyrol IV)."],["Ion Fe2+ ở trung tâm của nhóm Hem tạo được tối đa bao nhiêu liên kết phối trí?",["4 liên kết","5 liên kết","6 liên kết","8 liên kết"],2,"Giải thích: Ion Fe2+ có số phối trí là 6: 4 liên kết với 4 Nitơ của các nhân pyrol, 1 liên kết với N-imidazol của His F8 và 1 liên kết phối trí thứ 6 dành cho O2 (hoặc His E7 khi không có O2)."],["Liên kết phối trí thứ 5 của Fe2+ trong nhóm Hem gắn trực tiếp với gốc acid amin nào của chuỗi Globin?",["Histidin E7 (His xa / Distal)","Histidin F8 (His gần / Proximal)","Lysin B10","Valin E11"],1,"Giải thích: Liên kết phối trí thứ 5 của Fe2+ nối trực tiếp với Nitơ thuộc vòng Imidazol của gốc Histidin F8 (gọi là Histidin gần / Proximal Histidine)."],["Liên kết phối trí thứ 6 của ion Fe2+ trong phân tử Deoxyhemoglobin (khi chưa gắn O2) liên kết hoặc tương tác với:",["Gốc Histidin E7 (His xa)","Gốc Histidin F8 (His gần)","Gốc Alanin E14","Nhóm COOH tận của chuỗi alpha"],0,"Giải thích: Ở dạng Deoxyhemoglobin, vị trí phối trí thứ 6 của Fe2+ để trống hoặc tương tác yếu với Histidin E7 (His xa / Distal Histidine). Khi gắn O2, O2 xen vào giữa Fe2+ và His E7."],["Thành phần Hemoglobin chính (HbA1) ở máu người trưởng thành bình thường có cấu trúc chuỗi globin là:",["alpha2 beta2 (chứa 2 chuỗi alpha và 2 chuỗi beta)","alpha2 delta2","alpha2 gamma2","zeta2 epsilon2"],0,"Giải thích: Ở người trưởng thành bình thường, HbA1 (alpha2 beta2) chiếm tới 95 - 98% tổng lượng Hemoglobin trong máu. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 17 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Dạng Hemoglobin phụ (HbA2) ở người trưởng thành bình thường chiếm 2-3% có công thức chuỗi là:",["alpha2 gamma2","alpha2 delta2","alpha2 beta2","zeta2 beta2"],1,"Giải thích: HbA2 ở người trưởng thành có cấu trúc chuỗi gồm 2 chuỗi alpha và 2 chuỗi delta (alpha2 delta2), chiếm tỷ lệ 2 - 3%."],["Hemoglobin thai nhi (HbF / Fetal Hemoglobin) có công thức cấu tạo chuỗi globin là:",["alpha2 beta2","alpha2 delta2","alpha2 gamma2","zeta2 gamma2"],2,"Giải thích: HbF có cấu trúc chuỗi alpha2 gamma2, là dạng Hb ưu thế trong giai đoạn bào thai và giảm dần sau khi sinh."],["Số lượng acid amin trong chuỗi alpha và chuỗi beta của Hemoglobin người lần lượt là:",["141 và 146 acid amin","146 và 141 acid amin","141 và 141 acid amin","146 và 146 acid amin"],0,"Giải thích: Chuỗi alpha gồm 141 acid amin; chuỗi beta (cũng như chuỗi gamma và delta) gồm 146 acid amin."],["Cụm gen quy định tổng hợp các chuỗi globin họ alpha (gen alpha và zeta) nằm trên nhiễm sắc thể số:",["Nhiễm sắc thể 11","Nhiễm sắc thể 16","Nhiễm sắc thể 13","Nhiễm sắc thể 21"],1,"Giải thích: Cụm gen mã hóa cho họ chuỗi alpha-globin (gồm gen alpha1, alpha2 và zeta) nằm trên cánh ngắn của nhiễm sắc thể 16."],["Cụm gen quy định tổng hợp các chuỗi globin họ non-alpha (beta, gamma, delta, epsilon) nằm trên nhiễm sắc thể số:",["Nhiễm sắc thể 11","Nhiễm sắc thể 16","Nhiễm sắc thể 12","Nhiễm sắc thể 18"],0,"Giải thích: Các gen mã hóa cho các chuỗi beta, delta, gamma (Gy, Ay) và epsilon nằm trên cánh ngắn của nhiễm sắc thể 11."],["Phản ứng gắn kết giữa Hemoglobin và Oxy để tạo thành Oxyhemoglobin (HbO2) là phản ứng thuộc loại:",["Phản ứng oxy hóa sắt II thành sắt III","Phản ứng gắn kết thuận nghịch (gắn oxy hóa)","Phản ứng khử bất thuận nghịch","Phản ứng thủy phân chuỗi globin"],1,"Giải thích: Phản ứng kết hợp O2 với Hb là phản ứng thuận nghịch (oxy hóa gắn kết / oxygenation), trong đó Fe2+ không bị biến đổi hóa trị thành Fe3+."],["Một phân tử Hemoglobin hoàn chỉnh (tetramer) có khả năng gắn tối đa bao nhiêu phân tử khí O2?",["1 phân tử O2","2 phân tử O2","4 phân tử O2","8 phân tử O2"],2,"Giải thích: Vì mỗi phân tử Hb chứa 4 nhóm Hem (mỗi Hem chứa 1 Fe2+), nên 1 phân tử Hb gắn tối đa 4 phân tử O2 tạo Hb(O2)4."],["Đường cong phân ly Oxy-Hemoglobin (thể hiện mức độ bão hòa O2 theo phân áp O2) có dạng đặc trưng là:",["Đường thẳng tuyến tính","Đường hyperbole","Đường cong hình chữ S (sigmoidal curve)","Đường bậc hai parabol"],2,"Giải thích: Đường cong phân ly Oxy-Hb có dạng chữ S (sigmoidal), thể hiện tính hợp tác dương (positive cooperativity) giữa các bán đơn vị của Hb."],["Sự gắn phân tử O2 đầu tiên vào một bán đơn vị của Hb làm tăng ái lực gắn O2 của các bán đơn vị còn lại được gọi là:",["Hiệu ứng Bohr","Tương tác hợp tác dương (Positive cooperativity)","Hiệu ứng Haldane","Ức chế dị lập thể âm"],1,"Giải thích: Tương tác hợp tác dương xảy ra khi O2 gắn vào Hem 1 làm thay đổi cấu hình không gian làm cho các Hem 2, 3, 4 dễ dàng gắn O2 hơn."],["Trong quá trình gắn nhả Oxy, Hemoglobin chuyển đổi qua lại giữa hai trạng thái cấu hình không gian là:",["Trạng thái T (Tense - căng, ái lực thấp) và Trạng thái R (Relaxed - giãn, ái lực cao)","Trạng thái Alpha và Trạng thái Beta","Trạng thái Co (Compact) và Trạng thái Ex (Expanded)","Trạng thái Monomer và Dimer"],0,"Giải thích: Deoxyhemoglobin ở dạng T (Tense - căng do nhiều liên kết ion) có ái lực O2 thấp; khi gắn O2 chuyển sang dạng R (Relaxed - giãn) có ái lực O2 cao."],["Khi Hemoglobin chuyển từ trạng thái T (Deoxy) sang trạng thái R (Oxy), hai dimer alpha-beta quay xung quanh trục một góc là:",["5 độ","15 độ","30 độ","45 độ"],1,"Giải thích: Sự chuyển từ dạng T sang R kèm theo sự quay của cặp dimer alpha1-beta1 so với alpha2-beta2 một góc 15 độ quanh trục không gian."],["Hợp chất 2,3-Bisphosphoglycerate (2,3-BPG) điều hòa chức năng vận chuyển O2 của Hb bằng cách:",["Gắn vào hốc trung tâm làm bền dạng T, làm giảm ái lực của Hb với O2","Gắn vào Fe2+ ngăn O2 gắn vào Hem","Gắn vào dạng R làm tăng ái lực của Hb với O2","Phân hủy chuỗi beta của Hb"],0,"Giải thích: 2,3-BPG gắn vào hốc trung tâm nằm giữa 2 chuỗi beta ở dạng T, tạo các cầu liên kết ion làm bền dạng T, qua đó giảm ái lực O2 và tăng cường giải phóng O2 cho mô. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 18 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Tại sao Hemoglobin thai nhi (HbF) có ái lực gắn O2 cao hơn Hemoglobin người trưởng thành (HbA1)?",["HbF chứa 6 nhóm Hem","Chuỗi gamma của HbF gắn 2,3-BPG yếu hơn chuỗi beta của HbA1","HbF không có cấu trúc bậc 4","Chuỗi alpha của HbF gắn O2 trực tiếp không cần Fe2+"],1,"Giải thích: Ở chuỗi gamma của HbF, vị trí His-143 được thay bằng Serin, làm giảm điện tích dương trong hốc gắn 2,3-BPG nên gắn 2,3-BPG yếu hơn, dẫn đến ái lực O2 của HbF cao hơn HbA1, giúp lấy O2 từ máu mẹ."],["Khoảng 15 - 20% lượng khí CO2 được vận chuyển trực tiếp trong máu dưới dạng nào nhờ Hb?",["Dạng hòa tan tự do trong huyết tương","Dạng Carbamate (R-NH-COO-) gắn vào nhóm -NH2 đầu N-tận của chuỗi globin","Dạng gắn trực tiếp vào Fe2+ của Hem","Dạng khí CO2 nén trong hồng cầu"],1,"Giải thích: CO2 vận chuyển trực tiếp bằng cách gắn vào các nhóm amine tự do đầu N-tận (-NH2) của các chuỗi polypeptide tạo Carbaminohemoglobin (R-NH-COO-)."],["Phần lớn khí CO2 (khoảng 80 - 85%) được vận chuyển gián tiếp từ mô về phổi dưới dạng ion HCO3- nhờ enzyme nào trong hồng cầu?",["Carbonic Anhydrase (CA)","Lactate Dehydrogenase (LDH)","Cytochrome Oxidase","Glucose-6-Phosphate Dehydrogenase"],0,"Giải thích: Enzyme Carbonic Anhydrase (CA) trong hồng cầu xúc tác phản ứng CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3-, giúp vận chuyển CO2 dưới dạng HCO3-."],["Hiệu ứng Bohr (Bohr effect) mô tả mối quan hệ sinh lý nào sau đây?",["Sự tăng nồng độ H+ (pH giảm) hoặc tăng CO2 làm giảm ái lực của Hb với O2","Sự tăng phân áp O2 làm tăng khả năng gắn CO2","Sự giảm nhiệt độ làm tăng giải phóng O2 ở mô","Sự tăng 2,3-BPG làm tăng gắn O2 ở phổi"],0,"Giải thích: Hiệu ứng Bohr nêu rõ khi pH giảm (tăng H+) hoặc tăng pCO2 tại mô, Hb bị tăng ion hóa gốc His-146 làm bền dạng T, làm giảm ái lực O2 và đẩy O2 ra khỏi HbO2 cung cấp cho mô."],["Khí Carbon Monoxide (CO) gắn vào Hemoglobin tạo thành hợp chất rất bền vững là:",["Oxyhemoglobin (HbO2)","Carboxyhemoglobin (HbCO)","Carbaminohemoglobin","Methemoglobin (MetHb)"],1,"Giải thích: Khí CO kết hợp trực tiếp với Fe2+ của Hem tạo thành Carboxyhemoglobin (HbCO)."],["Ái lực liên kết của Hemoglobin với khí CO so với khí O2 cao hơn khoảng bao nhiêu lần?",["10 - 20 lần","50 - 100 lần","210 - 250 lần","1000 - 2000 lần"],2,"Giải thích: Hb có ái lực gắn với CO mạnh gấp khoảng 210 - 250 lần so với O2, do đó CO cạnh tranh và tranh chấp vị trí gắn O2 mãnh liệt."],["Nồng độ Carboxyhemoglobin (HbCO) trong máu đạt đến ngưỡng nào bắt đầu gây nguy cơ tử vong do ngạt mô?",["10%","20%","40%","Từ 60% trở lên"],3,"Giải thích: Khi nồng độ HbCO trong máu vượt quá 60%, bệnh nhân bị ngộ độc độc tính nặng, mô thiếu O2 trầm trọng dẫn đến tử vong."],["Methemoglobin (MetHb) là dạng Hemoglobin bất thường trong đó ion sắt bị biến đổi như thế nào?",["Fe2+ bị oxy hóa thành Fe3+","Fe2+ bị khử thành Fe0","Fe2+ bị thay thế bằng ion Cu2+","Fe2+ bị mất hoàn toàn khỏi vòng Hem"],0,"Giải thích: Methemoglobin hình thành khi ion Fe2+ trong Hem bị oxy hóa thành ion Fe3+ (sắt III)."],["Hậu quả sinh học chính khi Hemoglobin chuyển thành Methemoglobin là gì?",["Hồng cầu bị vỡ ngay lập tức trong lòng mạch","MetHb không còn khả năng vận chuyển O2 thuận nghịch cho mô","Làm máu có màu đỏ tươi bất thường","Làm tăng tổng hợp phân tử HbF"],1,"Giải thích: Fe3+ trong MetHb làm cho phân tử Hb mất khả năng gắn nhả O2 thuận nghịch, gây nên tình trạng xanh tím (cyanosis) và thiếu O2 mô."],["Hệ thống enzyme chính trong hồng cầu giữ nhiệm vụ khử MetHb (Fe3+) trở lại thành Hb (Fe2+) bình thường là:",["NADH-methemoglobin reductase (Cytochrome b5 reductase)","Glutathione peroxidase","Superoxide dismutase","Catalase"],0,"Giải thích: Enzyme NADH-methemoglobin reductase (Cytochrome b5 reductase) sử dụng NADH để khử Fe3+ trong MetHb trở lại Fe2+ hoạt động."],["Hemoglobin A1c (HbA1c) là sản phẩm gắn kết phi enzym giữa Glucose với vị trí nào trên Hb?",["Nhóm -NH2 tự do của acid amin Valin đầu N-tận của chuỗi beta","Nhóm -COOH của acid amin C-tận của chuỗi alpha","Ion Fe2+ của nhóm Hem","Nhóm Imidazol của Histidin F8"],0,"Giải thích: HbA1c hình thành do phản ứng ngưng tụ phi enzym giữa nhóm aldehyde của Glucose với nhóm -NH2 của Valin N-tận trên chuỗi beta."],["Phản ứng tạo thành HbA1c diễn ra qua 2 giai đoạn theo thứ tự là:",["Tạo Bazơ Schiff (không bền) -> Chuyển vị Amadori (bền vững)","Chuyển vị Amadori -> Tạo Bazơ Schiff","Phản ứng ester hóa -> Phản ứng khử","Phản ứng oxy hóa -> Phản ứng thủy phân"],0,"Giải thích: Phản ứng gắn glucose vào Hb ban đầu tạo hợp chất aldimine (Bazơ Schiff) không bền, sau đó biến đổi chậm bất thuận nghịch qua chuyển vị Amadori tạo ketoamine (HbA1c) bền vững. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 19 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Chỉ số xét nghiệm HbA1c phản ánh mức độ kiểm soát đường huyết trung bình của bệnh nhân trong khoảng thời gian bao lâu?",["1 - 2 tuần trước","2 - 3 tháng trước","6 tháng trước","1 năm trước"],1,"Giải thích: Vì đời sống hồng cầu là khoảng 120 ngày (4 tháng), nồng độ HbA1c phản ánh nồng độ đường huyết trung bình trong khoảng 2 - 3 tháng trước đó."],["Ngưỡng HbA1c theo Hiệp hội Đái tháo đường Hoa Kỳ (ADA) được sử dụng để chẩn đoán Đái tháo đường là:",[">= 5.7%",">= 6.0%",">= 6.5%",">= 7.0%"],2,"Giải thích: Theo tiêu chuẩn ADA, giá trị HbA1c >= 6.5% là một trong các tiêu chuẩn chẩn đoán xác định bệnh Đái tháo đường."],["Khả năng đệm pH của Hemoglobin trong máu chiếm khoảng bao nhiêu % tổng dung lượng đệm của máu toàn phần?",["20%","40%","70%","95%"],2,"Giải thích: Hemoglobin là hệ đệm quan trọng nhất trong tế bào hồng cầu và đóng góp khoảng 70% tổng khả năng đệm của máu toàn phần."],["Tác dụng đệm pH của Hemoglobin phụ thuộc chủ yếu vào nhóm chức của acid amin nào trong chuỗi Globin?",["Nhóm Imidazol của gốc Histidin","Nhóm Thiol (-SH) của gốc Cysteine","Nhóm Phenol của gốc Tyrosine","Nhóm Guanidine của gốc Arginine"],0,"Giải thích: Vòng Imidazol của các gốc Histidin trong chuỗi Globin có pKa gần với pH sinh lý của máu (~7.4), giúp nhường và nhận H+ hiệu quả."],["Nồng độ Hemoglobin trung bình ở người trưởng thành khỏe mạnh bình thường là:",["Nam: 13-16 g/dL; Nữ: 12-15 g/dL","Nam: 10-12 g/dL; Nữ: 8-10 g/dL","Nam: 18-20 g/dL; Nữ: 16-18 g/dL","Nam: 7-9 g/dL; Nữ: 6-8 g/dL"],0,"Giải thích: Giá trị sinh lý bình thường của nồng độ Hb ở nam giới là 13 - 16 g/dL (130-160 g/L) và ở nữ giới là 12 - 15 g/dL (120-150 g/L)."],["Điểm khác biệt quan trọng về cấu trúc và chức năng giữa Myoglobin (ở cơ) và Hemoglobin (ở hồng cầu) là:",["Myoglobin có 4 chuỗi polypeptide, Hemoglobin chỉ có 1 chuỗi","Myoglobin là monomer (1 chuỗi, 1 Hem), đường cong phân ly O2 hình hyperbole","Myoglobin vận chuyển CO2, Hemoglobin chỉ vận chuyển O2","Myoglobin không chứa Fe2+"],1,"Giải thích: Myoglobin là một monomer gồm 1 chuỗi polypeptide và 1 nhóm Hem, có ái lực O2 rất cao, đường cong phân ly dạng hyperbole, đóng vai trò dự trữ O2 ở cơ."],["Yếu tố nào sau đây làm dịch chuyển đường cong phân ly Oxy-Hemoglobin sang PHẢI (tăng nhả O2 cho mô)?",["Giảm nhiệt độ, tăng pH, giảm 2,3-BPG","Tăng H+ (giảm pH), tăng pCO2, tăng 2,3-BPG, tăng nhiệt độ","Giảm pCO2 và giảm H+","Xuất hiện CO nồng độ cao"],1,"Giải thích: Tăng H+ (pH giảm), tăng pCO2, tăng 2,3-BPG và tăng nhiệt độ đều làm tăng tính linh động và ổn định dạng T, đẩy đường cong sang phải, tăng giải phóng O2."],["Phần trăm khối lượng của nguyên tố Sắt (Fe) có trong một phân tử Hemoglobin xấp xỉ khoảng:",["0.05%","0.34%","1.25%","3.40%"],1,"Giải thích: Sắt chiếm khoảng 0.34% tổng khối lượng phân tử của Hemoglobin (4 nguyên tử Fe x 56 / 64.000 ≈ 0.35%)."],["Ở cấu trúc bậc 2 và bậc 3 của mỗi chuỗi Globin, tỷ lệ đoạn xoắn alpha chiếm khoảng:",["25 - 30%","50 - 55%","75 - 80%","95 - 100%"],2,"Giải thích: Khoảng 75 - 80% chiều dài chuỗi polypeptide của globin cuộn thành các đoạn xoắn alpha (gồm 8 đoạn đặt tên từ A đến H)."],["Liên kết giữ các bán đơn vị với nhau trong cấu trúc bậc 4 của phân tử Hemoglobin chủ yếu là:",["Liên kết cộng hóa trị đồng hóa trị","Liên kết yếu không cộng hóa trị (liên kết hydro, cầu muối ion, tương tác kỵ nước)","Liên kết ester","Liên kết peptid đặc biệt"],1,"Giải thích: Cấu trúc bậc 4 của Hb được duy trì nhờ các liên kết phi cộng hóa trị (liên kết hydro, liên kết ion giữa các nhóm mang điện và tương tác kỵ nước)."],["Hiện tượng tăng nồng độ 2,3-BPG trong hồng cầu là cơ chế thích nghi quan trọng của cơ thể trong tình huống nào?",["Ngộ độc khí CO","Bệnh nhân sống lâu ngày ở vùng núi cao hoặc bị thiếu máu mạn tính","Nhịn ăn kéo dài","Nhiễm kiềm hô hấp cấp"],1,"Giải thích: Khi lên vùng núi cao (phân áp O2 thấp) hoặc bị thiếu máu mạn, hồng cầu tăng tổng hợp 2,3-BPG để giảm ái lực O2 của Hb, giúp nhả O2 cho mô dễ dàng hơn. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 20 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Chuỗi Globin nào sau đây có trong cấu trúc Hemoglobin ở giai đoạn phôi sớm (Embryonic Hb)?",["Chuỗi epsilon (ε) và chuỗi zeta (ζ)","Chuỗi beta (β) và chuỗi delta (δ)","Chuỗi gamma (γ) duy nhất","Chuỗi alpha (α) duy nhất"],0,"Giải thích: Ở giai đoạn phôi thai sớm (tuần 4-8), các chuỗi globin được tổng hợp gồm chuỗi zeta (gần giống alpha) và chuỗi epsilon (gần giống beta) tạo Hb Gower 1 (zeta2 epsilon2)."],["Khi O2 gắn vào Fe2+ của nhóm Hem, vị trí của ion Fe2+ biến đổi như thế nào so với mặt phẳng vòng Porphyrin?",["Fe2+ bị đẩy ra xa khỏi mặt phẳng vòng 1.5 Å","Fe2+ nhích dịch chuyển vào trong mặt phẳng của vòng Porphyrin","Fe2+ tách rời hẳn khỏi vòng Porphyrin","Fe2+ không có sự thay đổi vị trí"],1,"Giải thích: Ở dạng Deoxy (T), Fe2+ nằm lệch ngoài mặt phẳng vòng Porphyrin khoảng 0.4 Å. Khi O2 gắn vào, Fe2+ bị kéo nhích vào đúng mặt phẳng vòng, kéo theo His F8 và làm thay đổi cấu hình tetramer."],["Dạng Hb nào sau đây KHÔNG có khả năng vận chuyển khí O2?",["HbA1","HbF","Methemoglobin (MetHb) và Carboxyhemoglobin (HbCO)","Oxyhemoglobin"],2,"Giải thích: MetHb (chứa Fe3+) và HbCO (chứa CO gắn chặt vào Fe2+) đều bị mất chức năng vận chuyển O2 bình thường cho mô."],["Chất nào sau đây là chất điều hòa dị lập thể dương (Positive allosteric effector) làm tăng ái lực của Hb với O2?",["Ion H+","2,3-BPG","Khí O2","Khí CO2"],2,"Giải thích: Chính bản thân phân tử O2 là chất điều hòa dị lập thể dương của Hb: sự gắn của 1 phân tử O2 làm tăng ái lực gắn các phân tử O2 tiếp theo."],["Quá trình sinh tổng hợp Hem diễn ra chủ yếu nhất ở hai cơ quan nào trong cơ thể?",["Tủy xương (85%) và Gan (15%)","Thận (70%) và Lách (30%)","Cơ vân (60%) và Não (40%)","Ruột non (50%) và Tụy (50%)"],0,"Giải thích: Tổng hợp Hem diễn ra ở tất cả các tế bào có hemoprotein, nhưng mạnh nhất là ở tế bào tiền thân hồng cầu tại Tủy xương (~85%) và tế bào gan (~15%)."],["Các phản ứng của quá trình sinh tổng hợp Hem phân bố ở những bào quan nào trong tế bào?",["Toàn bộ trong Nhân tế bào","Toàn bộ trong Bào tương","Phân bố ở cả Ti thể và Bào tương","Toàn bộ trong Bộ máy Golgi"],2,"Giải thích: Quá trình tổng hợp Hem bắt đầu ở Ti thể (tạo ALA), chuyển ra Bào tương (tạo PBG đến Protoporphyrinogen IX), rồi quay trở lại Ti thể (tạo Protoporphyrin IX và gắn Fe2+)."],["Hai nguyên liệu đầu tiên ngưng tụ để khởi đầu quá trình tổng hợp Hem là:",["Acetyl-CoA và Alanine","Succinyl-CoA và Glycine","Oxaloacetate và Glutamate","Pyruvate và Aspartate"],1,"Giải thích: Phản ứng mở đầu tổng hợp Hem là sự ngưng tụ giữa Succinyl-CoA (từ chu trình Krebs) và acid amin Glycine."],["Phản ứng ngưng tụ Succinyl-CoA và Glycine tạo thành delta-Aminolevulinic acid (ALA) được xúc tác bởi enzyme nào?",["ALA synthase (ALAS)","ALA dehydratase","PBG deaminase","Ferrochelatase"],0,"Giải thích: Enzyme ALA synthase (ALAS) nằm ở ti thể xúc tác phản ứng tạo ALA từ Succinyl-CoA và Glycine."],["Coenzyme bắt buộc cho hoạt động xúc tác của enzyme ALA synthase là:",["NADP+","Pyridoxal phosphate (PLP / Vitamin B6)","Thiamin pyrophosphate (TPP)","Tetrahydrofolate (THF)"],1,"Giải thích: Enzyme ALA synthase cần coenzyme Pyridoxal phosphate (PLP / Vitamin B6) để hoạt hóa gốc Glycine."],["Bước phản ứng nào đóng vai trò là bước hạn chế tốc độ (rate-limiting step) điều hòa toàn bộ con đường tổng hợp Hem?",["Phản ứng tạo ALA xúc tác bởi ALA synthase","Phản ứng gắn Fe2+ bởi Ferrochelatase","Phản ứng tạo PBG bởi ALA dehydratase","Phản ứng đóng vòng Uroporphyrinogen III"],0,"Giải thích: Phản ứng tạo ALA do ALA synthase xúc tác là bước điều hòa mấu chốt quyết định tốc độ tổng hợp Hem của tế bào."],["Sự khác biệt quan trọng trong cơ chế điều hòa enzyme ALAS1 (ở gan) và ALAS2 (ở tủy xương) là:",["ALAS1 bị ức chế ngược bởi Hem; ALAS2 được điều hòa bởi nồng độ Sắt Fe2+","ALAS1 bị kích thích bởi Hem; ALAS2 bị ức chế bởi Fe2+","ALAS1 nằm ở bào tương; ALAS2 nằm ở nhân","ALAS1 không cần coenzyme B6"],0,"Giải thích: Ở gan, ALAS1 bị kìm hãm theo cơ chế ức chế ngược âm tính bởi sản phẩm Hem/Hematin; ở tủy xương, ALAS2 được kích thích tổng hợp dựa trên lượng sắt sẵn có."],["Phản ứng ngưng tụ 2 phân tử ALA ở bào tương để tạo thành Porphobilinogen (PBG) do enzyme nào xúc tác?",["ALA dehydratase (PBG synthase)","PBG deaminase","Uroporphyrinogen III synthase","Coproporphyrinogen oxidase"],0,"Giải thích: ALA dehydratase (còn gọi là PBG synthase) xúc tác tách 2 phân tử H2O từ 2 phân tử ALA để tạo thành 1 phân tử PBG mang vòng pyrol. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 21 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Ngộ độc chất nào sau đây ức chế mạnh enzyme ALA dehydratase và Ferrochelatase, gây thiếu máu và tăng ALA trong nước tiểu?",["Ngộ độc Chì (Pb2+)","Ngộ độc Thủy ngân (Hg2+)","Ngộ độc Arsen","Ngộ độc Cadmium"],0,"Giải thích: Ngộ độc chì (Lead poisoning) ức chế enzyme chứa nhóm -SH như ALA dehydratase và Ferrochelatase, cản trở tổng hợp Hem gây thiếu máu."],["Bốn phân tử Porphobilinogen (PBG) ngưng tụ giải phóng 4 NH3 tạo thành Hydroxymethylbilane (HMB) nhờ enzyme:",["PBG deaminase (HMB synthase)","Uroporphyrinogen decarboxylase","Ferrochelatase","Heme oxygenase"],0,"Giải thích: Enzyme PBG deaminase (còn gọi là HMB synthase) xúc tác ngưng tụ 4 phân tử PBG chuỗi thẳng tạo nên Hydroxymethylbilane."],["Enzyme xúc tác đóng vòng Hydroxymethylbilane tạo thành Uroporphyrinogen III là:",["Uroporphyrinogen III synthase","PBG deaminase","Uroporphyrinogen decarboxylase","Protoporphyrinogen oxidase"],0,"Giải thích: Uroporphyrinogen III synthase xúc tác phản ứng đóng vòng và đảo ngược vòng pyrol IV tạo uroporphyrinogen III."],["Phản ứng khử carboxyl chuyển Uroporphyrinogen III thành Coproporphyrinogen III do enzyme nào thực hiện?",["Uroporphyrinogen decarboxylase","ALA dehydratase","Ferrochelatase","Coproporphyrinogen oxidase"],0,"Giải thích: Enzyme Uroporphyrinogen decarboxylase loại bỏ 4 CO2 từ 4 nhóm Acetic (-CH2-COOH) biến chúng thành 4 nhóm Methyl (-CH3)."],["Phản ứng biến đổi Coproporphyrinogen III thành Protoporphyrinogen IX diễn ra ở đâu và do enzyme nào xúc tác?",["Tại ti thể, do Coproporphyrinogen oxidase xúc tác","Tại bào tương, do PBG deaminase xúc tác","Tại lưới nội chất, do UGT xúc tác","Tại nhân, do Heme oxygenase xúc tác"],0,"Giải thích: Coproporphyrinogen III từ bào tương đi vào ti thể, bị enzyme Coproporphyrinogen oxidase oxy hóa 2 nhóm Propionic thành Vinyl tạo Protoporphyrinogen IX."],["Giai đoạn cuối cùng của quá trình tổng hợp Hem là phản ứng gắn Fe2+ vào Protoporphyrin IX do enzyme nào xúc tác?",["Ferrochelatase (Heme synthase)","ALA synthase","Biliverdin reductase","Heme oxygenase"],0,"Giải thích: Enzyme Ferrochelatase (Heme synthase) tại màng trong ti thể xúc tác gắn ion Fe2+ vào trung tâm Protoporphyrin IX tạo Hem."],["Bệnh Porphyria là nhóm bệnh lý di truyền do nguyên nhân nào sau đây?",["Khiếm khuyết di truyền thiếu hụt một trong các enzyme trong con đường tổng hợp Hem","Thừa enzyme ALA synthase ở tủy xương","Tăng phá hủy hồng cầu quá mức ở lách","Thiếu vitamin C kéo dài"],0,"Giải thích: Porphyria là nhóm rối loạn di truyền do thiếu hụt một trong các enzyme tổng hợp Hem, gây tích tụ và đào thải bất thường các tiền chất Porphyrin."],["Bệnh Porphyria cấp ngắt quãng (Acute Intermittent Porphyria - AIP) xuất hiện do thiếu hụt enzyme nào?",["PBG deaminase (HMB synthase)","Ferrochelatase","Uroporphyrinogen III synthase","ALA dehydratase"],0,"Giải thích: AIP là bệnh di truyền trội NST thường do thiếu PBG deaminase, dẫn đến tích tụ ALA và PBG gây đau bụng cấp và triệu chứng thần kinh."],["Thể bệnh Porphyria da phổ biến nhất (Porphyria cutanea tarda - PCT) gây tổn thương bọng nước trên da vùng hở là do thiếu enzyme:",["Uroporphyrinogen decarboxylase","ALA synthase","Protoporphyrinogen oxidase","Ferrochelatase"],0,"Giải thích: Porphyria cutanea tarda (PCT) xuất hiện do giảm hoạt tính enzyme Uroporphyrinogen decarboxylase, làm ứ đọng uroporphyrin gây nhạy cảm ánh sáng da."],["Sự tổng hợp chuỗi polypeptide Globin xảy ra tại bào quan nào trong tế bào tiền thân hồng cầu?",["Ribosome trong bào tương","Ti thể","Nhân tế bào","Peroxisome"],0,"Giải thích: Các chuỗi globin được dịch mã và tổng hợp trên các polyribosome nằm trong bào tương của hồng cầu lưới."],["Loại protein chaperon chuyên biệt giúp bảo vệ và ổn định chuỗi alpha-globin tự do không bị kết tụ khi chưa kịp gắn chuỗi beta là:",["AHSP (Alpha-hemoglobin stabilizing protein)","Hsp70","Albumin","Transferrin"],0,"Giải thích: AHSP là một protein chaperon gắn đặc hiệu với chuỗi alpha tự do, giữ cho chuỗi alpha hòa tan và ngăn ngừa kết tụ độc hại trước khi dimer hóa với chuỗi beta. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 22 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Đời sống trung bình của tế bào hồng cầu trưởng thành lưu hành trong máu ngoại vi ở người bình thường là:",["30 - 60 ngày","100 - 120 ngày","180 - 200 ngày","365 ngày"],1,"Giải thích: Hồng cầu trưởng thành lưu hành trong máu có tuổi thọ trung bình từ 100 đến 120 ngày trước khi bị tiêu hủy."],["Quá trình phá hủy hồng cầu già và thoái hóa Hemoglobin diễn ra chủ yếu (khoảng 90%) tại đâu?",["Hệ liên võng nội mô (Lách, Gan, Tủy xương)","Trong lòng mạch máu ngoại vi","Tại ống thận","Tại niêm mạc ruột non"],0,"Giải thích: Khoảng 90% hồng cầu già bị tiêu hủy bởi các đại thực bào của Hệ liên võng nội mô (chủ yếu ở Lách, sau đó là Gan và Tủy xương)."],["Khoảng 10% Hemoglobin giải phóng trực tiếp vào lòng mạch (thoái hóa nội mạch) được gắn ngay với protein huyết tương nào để tránh mất qua thận?",["Haptoglobin","Albumin","Transferrin","Ceruloplasmin"],0,"Giải thích: Haptoglobin là một glycoprotein huyết tương gắn đặc hiệu với dimer Hb tự do trong lòng mạch tạo phức hợp kích thước lớn ngăn lọc qua cầu thận."],["Phức hợp Hb-Haptoglobin trong máu được đưa về cơ quan nào để xử lý thoái hóa?",["Tế bào Kupffer của Gan","Ống lượn gần của Thận","Tế bào cơ tim","Niêm mạc phế quản"],0,"Giải thích: Phức hợp Hb-Haptoglobin được gắn vào thụ thể CD163 trên tế bào Kupffer (đại thực bào gan) và bị thu nhận thoái hóa."],["Trong quá trình thoái hóa Hemoglobin, phần protein Globin được xử lý như thế nào?",["Đào thải nguyên vẹn qua nước tiểu","Thủy phân thành các acid amin tự do để tái sử dụng hoặc thoái hóa","Biến đổi thành sắc tố mật","Chuyển thành Cholesterol"],1,"Giải thích: Globin được các enzyme protease thủy phân thành các acid amin tự do đưa vào quỹ acid amin chung của cơ thể."],["Sắt (Fe2+) giải phóng từ sự thoái hóa Hem được vận chuyển trong máu nhờ protein nào và dự trữ dưới dạng nào tại gan?",["Vận chuyển bởi Transferrin, dự trữ dưới dạng Ferritin và Hemosiderin","Vận chuyển bởi Albumin, dự trữ dạng Hemoglobin","Vận chuyển bởi Haptoglobin, dự trữ dạng Myoglobin","Vận chuyển bởi Globulin, dự trữ dạng Billirubin"],0,"Giải thích: Sắt giải phóng được vận chuyển bởi Transferrin trong huyết thanh về tủy xương để tạo hồng cầu mới hoặc dự trữ dưới dạng Ferritin / Hemosiderin ở gan."],["Phản ứng mở vòng Hem tại cầu nối alpha-methenyl giải phóng khí CO và Fe2+ tạo thành sắc tố màu xanh ve có tên là:",["Biliverdin","Bilirubin","Stercobilin","Urobilin"],0,"Giải thích: Mở vòng Hem bởi Heme oxygenase tạo ra sản phẩm trung gian có màu xanh ve gọi là Biliverdin."],["Enzyme xúc tác phản ứng mở vòng Hem oxy hóa giải phóng Fe2+ và khí CO là:",["Heme oxygenase","Biliverdin reductase","UDP-glucuronosyltransferase","Ferrochelatase"],0,"Giải thích: Heme oxygenase (HO) xúc tác phản ứng mở vòng Hem sử dụng O2 và NADPH giải phóng Fe2+, CO và tạo Biliverdin."],["Khí độc duy nhất được sản sinh nội sinh trong cơ thể người từ quá trình thoái hóa Hem là:",["Carbon Monoxide (CO)","Carbon Dioxide (CO2)","Hydrogen Sulfide (H2S)","Methane (CH4)"],0,"Giải thích: Khí CO là sản phẩm khí duy nhất được sản xuất nội sinh trong cơ thể do phản ứng thoái hóa Hem xúc tác bởi Heme oxygenase."],["Phản ứng khử Biliverdin thành Bilirubin tự do (Bilirubin gián tiếp) do enzyme nào xúc tác?",["Biliverdin reductase (cần NADPH)","Heme oxygenase","Glucuronidase","Catalase"],0,"Giải thích: Biliverdin reductase sử dụng coenzyme NADPH để khử Biliverdin màu xanh ve thành Bilirubin tự do (gián tiếp) màu vàng."],["Tính chất vật lý và sinh hóa đặc trưng của Bilirubin tự do (Bilirubin gián tiếp) là:",["Không tan trong nước, độc với hệ thần kinh, tan trong mỡ, có ái lực cao với Albumin","Tan tốt trong nước, không độc, đào thải dễ dàng qua nước tiểu","Có màu xanh lục, phản ứng Diazo trực tiếp nhanh","Tan trong nước và kết hợp với Acid Uric"],0,"Giải thích: Bilirubin gián tiếp là chất không tan trong nước, có tính độc (đặc biệt với tế bào thần kinh trẻ sơ sinh), tan trong lipid và gắn chặt với Albumin trong máu."],["Trong phản ứng định lượng Van den Bergh (Diazo), Bilirubin gián tiếp được gọi tên dựa trên đặc điểm phản ứng nào?",["Cho phản ứng Diazo chậm, chỉ hiện màu sau khi thêm alcohol hoặc dung môi hỗ trợ","Hiện màu đỏ tía lập tức không cần cồn","Không bao giờ cho phản ứng Diazo","Tạo kết tủa trắng với dung dịch Diazo"],0,"Giải thích: Bilirubin tự do được gọi là 'gián tiếp' vì nó gắn chặt với Albumin và không tan trong nước nên phản ứng Diazo diễn ra rất chậm, chỉ hiện màu sau khi thêm cồn (alcohol) để giải phóng nó khỏi Albumin. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 23 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Protein huyết tương đảm nhận vai trò vận chuyển Bilirubin gián tiếp từ nơi sản xuất (hệ liên võng nội mô) về Gan là:",["Albumin (1 phân tử Albumin gắn tối đa 2 phân tử Bilirubin)","Haptoglobin","Fibrinogen","Transferrin"],0,"Giải thích: Albumin huyết thanh có 2 vị trí gắn Bilirubin gián tiếp, giúp vận chuyển chất không tan này trong dòng máu về gan an toàn."],["Khi về đến tế bào gan, Bilirubin gián tiếp tách khỏi Albumin và được đưa vào bào tương nhờ hai loại protein vận chuyển nội bào nào?",["Protein Ligandin (Protein Y) và Protein Z","Ferritin và Transferrin","Actin và Myosin","Apolipoprotein A và B"],0,"Giải thích: Tại bề mặt tế bào gan, Bilirubin tách khỏi Albumin và được thu nhận bởi các protein bào tương Ligandin (Protein Y / GST) và Protein Z."],["Quá trình liên hợp Bilirubin tại màng lưới nội chất của tế bào gan sử dụng chất cho acid glucuronic nào?",["UDP-Glucuronic acid (UDPGA)","Glucose-6-Phosphate","UDP-Glucose","Glucuronic acid tự do"],0,"Giải thích: Bilirubin liên hợp với 2 phân tử acid glucuronic được cung cấp từ UDP-Glucuronic acid (UDPGA)."],["Enzyme mấu chốt xúc tác phản ứng liên hợp Bilirubin tại tế bào gan để tạo thành Bilirubin diglucuronide (Bilirubin trực tiếp) là:",["UDP-glucuronosyltransferase (UGT1A1)","Heme oxygenase","Glucuronidase","Biliverdin reductase"],0,"Giải thích: Enzyme UDP-glucuronosyltransferase (UGT1A1) ở màng lưới nội chất tế bào gan xúc tác gắn 2 gốc glucuronate vào Bilirubin tạo Bilirubin liên hợp (trực tiếp)."],["Tính chất sinh hóa đặc trưng của Bilirubin trực tiếp (Bilirubin liên hợp) khác biệt với Bilirubin gián tiếp là:",["Tan tốt trong nước, không độc, phản ứng Diazo nhanh trực tiếp, xuất hiện trong nước tiểu khi đường mật bị tắc","Không tan trong nước, gây độc thần kinh nặng","Tan trong mỡ và gắn chặt với Albumin","Có màu xanh lục và bị hủy bởi ánh sáng xanh"],0,"Giải thích: Bilirubin trực tiếp là dạng đã liên hợp acid glucuronic nên tan tốt trong nước, không độc, phản ứng Diazo trực tiếp nhanh và đào thải qua mật/nước tiểu."],["Khi Bilirubin trực tiếp bài tiết theo dịch mật xuống ruột non, vi khuẩn ruột khử liên hợp và khử màu tạo thành hợp chất không màu là:",["Urobilinogen và Stercobilinogen","Biliverdin","Cholesterol","Protoporphyrin"],0,"Giải thích: Tại ruột, hệ vi khuẩn khử glucuronide và khử Bilirubin thành các sắc tố không màu là Urobilinogen và Stercobilinogen."],["Sắc tố tạo nên màu vàng nâu đặc trưng cho phân ở người bình thường là:",["Stercobilin (do Stercobilinogen bị oxy hóa)","Bilirubin gián tiếp","Biliverdin","Hemoglobin"],0,"Giải thích: Stercobilinogen ở đại tràng bị oxy hóa bởi không khí thành Stercobilin có màu vàng nâu tạo nên màu sắc tự nhiên của phân."],["Hiện tượng Chu trình Gan - Ruột (Enterohepatic circulation) của Urobilinogen mô tả quá trình nào?",["Khoảng 10 - 15% Urobilinogen ở ruột được tái hấp thu qua tĩnh mạch cửa về Gan và tái bài tiết vào Mật hoặc đào thải qua Thận","Toàn bộ Bilirubin được hấp thu lại từ dạ dày về tim","Sự vận chuyển mỡ từ ruột về gan","Sự tái hấp thu muối mật ở tá tràng"],0,"Giải thích: Khoảng 10-15% Urobilinogen được tái hấp thu ở hồi tràng vào máu tĩnh mạch cửa trở về gan, 1 phần nhỏ qua thận vào nước tiểu."],["Nước tiểu người bình thường có màu vàng nhạt là do sự có mặt của sắc tố nào được hình thành từ Urobilinogen bị oxy hóa?",["Urobilin","Stercobilin","Bilirubin trực tiếp","Porphyrin"],0,"Giải thích: Một phần nhỏ Urobilinogen bài tiết ra nước tiểu bị oxy hóa khi tiếp xúc không khí tạo thành Urobilin màu vàng nhạt."],["Tình trạng Vàng da (Jaundice / Icterus) trên lâm sàng bắt đầu quan sát rõ nhất ở mắt và da khi nồng độ Bilirubin toàn phần trong máu vượt quá:",["> 1.2 mg/dL (> 20 umol/L)","> 2.5 mg/dL (> 43 umol/L)","> 5.0 mg/dL (> 85 umol/L)","> 10 mg/dL (> 170 umol/L)"],1,"Giải thích: Vàng da tiềm ẩn khi Bilirubin T từ 1.2-2.5 mg/dL; khi Bilirubin T > 2.5 mg/dL (43 umol/L) biểu hiện vàng da niêm rõ trên lâm sàng."],["Nồng độ tham chiếu bình thường của Bilirubin toàn phần, Bilirubin gián tiếp và Bilirubin trực tiếp trong huyết thanh người lớn lần lượt là:",["Toàn phần: 0.8-1.2 mg/dL; Gián tiếp: 0.6-0.8 mg/dL; Trực tiếp: 0.2-0.4 mg/dL","Toàn phần: 3-5 mg/dL; Gián tiếp: 2-3 mg/dL; Trực tiếp: 1-2 mg/dL","Toàn phần: 0.1-0.2 mg/dL; Gián tiếp: 0.05 mg/dL; Trực tiếp: 0.05 mg/dL","Toàn phần: 10-15 mg/dL; Gián tiếp: 8-10 mg/dL; Trực tiếp: 2-5 mg/dL"],0,"Giải thích: Giá trị sinh lý bình thường: Bilirubin toàn phần 0.8-1.2 mg/dL, trong đó Bilirubin gián tiếp chiếm 80% (0.6-0.8 mg/dL) và Bilirubin trực tiếp (0.2-0.4 mg/dL). Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 24 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Trong trường hợp Vàng da Trước gan (Vàng da tán huyết do vỡ hồng cầu hàng loạt), biến đổi xét nghiệm đặc trưng là:",["Bilirubin gián tiếp tăng rất cao; Nước tiểu KHÔNG có sắc tố mật; Urobilinogen nước tiểu TĂNG; Phân sẫm màu","Bilirubin trực tiếp tăng vọt; Phân bạc màu","Men gan ALT, AST tăng gấp 100 lần","Nước tiểu có sắc tố mật dương tính rất mạnh"],0,"Giải thích: Tán huyết làm sản sinh quá nhiều Bilirubin gián tiếp vượt khả năng liên hợp của gan. Bil gián tiếp không qua được cầu thận nên nước tiểu không có sắc tố mật (-), nhưng Urobilinogen tăng mạnh, phân sẫm màu."],["Nguyên nhân nào sau đây gây ra tình trạng Vàng da Trước gan (tán huyết)?",["Sốt rét, bất đồng nhóm máu ABO/Rh, thiếu hụt enzyme G6PD, bệnh hồng cầu hình liềm","Sỏi ống mật chủ","Ung thư đầu tụy","Viêm gan virus B cấp"],0,"Giải thích: Các tình trạng gây vỡ hồng cầu hàng loạt như sốt rét, truyền nhầm nhóm máu, thiếu G6PD, bệnh HbS... là nguyên nhân gây vàng da trước gan."],["Trong trường hợp Vàng da Sau gan (Vàng da tắc mật do sỏi mật hoặc u đầu tụy chèn ép), biến đổi xét nghiệm đặc trưng là:",["Bilirubin trực tiếp tăng vọt; Phân nhạt màu/bạc màu như phân cò; Nước tiểu sẫm màu (sắc tố mật ++); Urobilinogen nước tiểu giảm/âm tính","Bilirubin gián tiếp tăng cao duy nhất; Phân sẫm màu","Urobilinogen nước tiểu tăng rất cao","Không xuất hiện sắc tố mật trong nước tiểu"],0,"Giải thích: Tắc mật làm Bilirubin trực tiếp ứ lại tràn vào máu và đào thải qua nước tiểu (sắc tố mật ++). Mật không xuống được ruột làm phân bạc màu (thiếu stercobilin) và Urobilinogen nước tiểu âm tính."],["Xét nghiệm enzyme huyết thanh nào tăng đặc hiệu nhất trong các trường hợp Vàng da Sau gan (tắc mật)?",["Alkaline Phosphatase (ALP) và Gamma-Glutamyl Transferase (GGT)","Creatine Kinase (CK-MB)","Amylase và Lipase","Lactate Dehydrogenase (LDH-1)"],0,"Giải thích: Tắc mật kích thích tổng hợp và giải phóng enzyme ALP và GGT ở màng ống mật, là chỉ thị đặc hiệu cho tình trạng ứ mật/tắc mật."],["Sự biến đổi xét nghiệm huyết thanh trong Vàng da Tại gan (nhu mô gan do viêm gan virus hay xơ gan) là:",["Tăng cả Bilirubin gián tiếp và Bilirubin trực tiếp; Men gan ALT, AST tăng cao","Chỉ tăng duy nhất Bilirubin trực tiếp","Phân sẫm màu đen","Nước tiểu hoàn toàn bình thường"],0,"Giải thích: Tổn thương nhu mô gan vừa làm giảm khả năng thu nhận/liên hợp (tăng Bil gián tiếp) vừa làm vỡ tế bào gan giải phóng Bil liên hợp vào máu (tăng Bil trực tiếp) kèm tăng men gan ALT/AST."],["Hội chứng Gilbert là một bất thường di truyền lành tính gây tăng nhẹ Bilirubin gián tiếp do nguyên nhân nào?",["Giảm hoạt tính enzyme UDP-glucuronosyltransferase (UGT1A1) xuống còn khoảng 30%","Tắc hoàn toàn ống mật chủ","Tán huyết cấp tính","Thiếu hụt Haptoglobin"],0,"Giải thích: Hội chứng Gilbert do đột biến vùng promoter gen UGT1A1 làm giảm tổng hợp enzyme UGT1A1 (~30% bình thường), gây tăng nhẹ Bil gián tiếp khi đói hoặc sốt."],["Hội chứng Crigler-Najjar tuýp I là bệnh di truyền nguy hiểm ở trẻ sơ sinh do nguyên nhân nào sau đây?",["Mất hoàn toàn (0%) hoạt tính enzyme UGT1A1 gây tăng Bilirubin gián tiếp cực cao và vàng da nhân não (Kernicterus)","Tăng hoạt tính enzyme Heme oxygenase","Tắc đường mật bẩm sinh","Thiếu hụt vitamin K"],0,"Giải thích: Crigler-Najjar tuýp I là bệnh lặn NST thường do đột biến mất hoàn toàn enzyme UGT1A1, làm Bil gián tiếp tăng rất cao ngấm vào nhân xám não gây tử vong."],["Hai hội chứng di truyền Dubin-Johnson và Rotor có đặc điểm chung là gây tăng loại Bilirubin nào trong máu?",["Tăng Bilirubin trực tiếp (liên hợp) do giảm bài tiết Bilirubin từ tế bào gan vào vi quản mật","Tăng Bilirubin gián tiếp do tán huyết","Giảm Bilirubin toàn phần","Tăng sản xuất Hemoprotein ở tủy xương"],0,"Giải thích: Hội chứng Dubin-Johnson và Rotor đều là rối loạn di truyền làm giảm khả năng vận chuyển và bài tiết Bilirubin trực tiếp từ tế bào gan vào ống mật, gây tăng Bil trực tiếp trong máu."],["Vàng da sinh lý ở trẻ sơ sinh thường xuất hiện vào ngày thứ mấy sau sinh và do cơ chế chính nào?",["Xuất hiện ngày 2 - 3 sau sinh; do enzyme UGT1A1 chưa trưởng thành kết hợp tốc độ hủy hồng cầu thai nhi tăng","Xuất hiện ngay trong 24 giờ đầu sau sinh; do tắc mật bẩm sinh","Xuất hiện sau 1 tháng; do nhiễm khuẩn gan","Xuất hiện ngày 10 sau sinh; do bất đồng nhóm máu ABO"],0,"Giải thích: Vàng da sinh lý sơ sinh thường xuất hiện ngày thứ 2-3 sau sinh, đạt đỉnh ngày 4-5 do hệ enzyme UGT1A1 gan chưa hoàn thiện kết hợp vỡ hồng cầu thai nhi (HbF -> HbA)."],["Phương pháp chiếu đèn (Phototherapy) điều trị vàng da sơ sinh sử dụng ánh sáng xanh (bước sóng 420-490 nm) dựa trên cơ chế sinh hóa nào?",["Chuyển Bilirubin gián tiếp không tan thành các đồng phân quang học (Lumirubin) tan trong nước để đào thải qua mật và nước tiểu","Phân hủy hoàn toàn phân tử Bilirubin thành CO2 và H2O","Kích thích gan tổng hợp thêm enzyme UGT1A1 lập tức","Tiêu diệt vi khuẩn ruột"],0,"Giải thích: Liệu pháp chiếu đèn dùng ánh sáng xanh biến đổi Bilirubin gián tiếp ở da thành đồng phân cấu trúc Lumirubin có tính tan trong nước, dễ dàng đào thải mà không cần gan liên hợp. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 25 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Bệnh lý Thalassemia (thiếu máu vùng biển) là nhóm bệnh lý di truyền do bất thường ở cấp độ nào của Hemoglobin?",["Giảm hoặc mất hoàn toàn sự tổng hợp một hoặc nhiều chuỗi globin bình thường","Đột biến cấu trúc nhóm Hem","Thiếu hụt sắt nghiêm trọng","Tăng tổng hợp quá mức cả chuỗi alpha và beta"],0,"Giải thích: Thalassemia là bệnh di truyền do đột biến làm giảm hoặc không tổng hợp được chuỗi globin bình thường (alpha hoặc beta-globin)."],["Ở bệnh nhi mắc Alpha-Thalassemia thể mất cả 4 gen alpha (Genotype --/--), thai nhi thường bị tử vong trong tử cung (phù thai) do tạo thành loại Hb bất thường nào?",["Hb Bart's (cấu trúc gamma4 có ái lực O2 cực cao không nhả O2 cho mô)","Hb H (beta4)","HbS","HbE"],0,"Giải thích: Mất cả 4 gen alpha làm thai nhi không tổng hợp được chuỗi alpha, tạo thành Hb Bart's (tetramer gamma4) gắn O2 cực chặt không nhả cho mô gây phù thai và tử vong."],["Bệnh Hb H trong Alpha-Thalassemia xuất hiện khi thiếu hụt bao nhiêu gen alpha và có cấu trúc chuỗi bất thường là gì?",["Thiếu 3 gen alpha; cấu trúc tetramer beta4 (Hb H)","Thiếu 1 gen alpha; cấu trúc gamma4","Thiếu 2 gen alpha; cấu trúc delta4","Thiếu 4 gen alpha; cấu trúc alpha4"],0,"Giải thích: Bệnh Hb H xảy ra khi mất 3 gen alpha (genotype --/-a), làm dư thừa chuỗi beta tạo thành tetramer beta4 (Hb H) kém bền dễ gây tán huyết."],["Bệnh Beta-Thalassemia thể nặng (đồng hợp tử / Thalassemia major) có biến đổi Hb nào đặc trưng trên điện di Hemoglobin?",["HbF tăng rất cao (chiếm 20 - 80%) và HbA1 giảm nặng hoặc mất hoàn toàn","HbA1 chiếm 99%","HbA2 giảm xuống 0%","Không có sự xuất hiện của HbF"],0,"Giải thích: Beta-Thalassemia thể nặng do thiếu hụt trầm trọng chuỗi beta, cơ thể bù trừ bằng cách duy trì tổng hợp chuỗi gamma làm HbF (alpha2 gamma2) tăng vọt đến 20 - 80%."],["Bệnh hồng cầu hình liềm (Hemoglobin S - HbS) xuất hiện do đột biến điểm nào trên chuỗi beta-globin?",["Acid glutamic ở vị trí thứ 6 bị thay thế bằng Valine (Glu6Val)","Acid glutamic ở vị trí thứ 6 bị thay thế bằng Lysine","Acid glutamic ở vị trí thứ 26 bị thay thế bằng Lysine","Valin ở vị trí thứ 1 bị mất đi"],0,"Giải thích: Bệnh HbS do đột biến điểm ở codon 6 của gen beta-globin: mã GAG (Acid glutamic - kỵ nước) bị biến đổi thành GTG (Valine - kỵ nước)."],["Cơ chế làm hồng cầu biến dạng thành hình liềm ở bệnh nhân mắc HbS khi phân áp O2 giảm là do:",["Valin kỵ nước ở vị trí 6 làm các phân tử Deoxy-HbS dính kết tạo thành các sợi polyme hình que dài làm biến dạng màng hồng cầu","Chuỗi alpha bị phân hủy nhanh chóng","Nhóm Hem bị tách khỏi Globin","Tế bào hồng cầu bị trương phồng do tích nước"],0,"Giải thích: Ở trạng thái Deoxy, gốc Valin kỵ nước ở vị trí 6 của chuỗi beta HbS bộc lộ ra ngoài và tương tác kỵ nước với phân tử HbS khác tạo sợi polymer kết tủa làm màng hồng cầu kéo dài thành hình liềm."],["Bệnh Hemoglobin E (HbE) phổ biến ở khu vực Đông Nam Á và Việt Nam là do đột biến điểm nào trên chuỗi beta?",["Acid glutamic ở vị trí 26 bị thay bằng Lysine (Glu26Lys)","Acid glutamic ở vị trí 6 bị thay bằng Valine","Histidin ở vị trí 63 bị thay bằng Tyrosine","Glycine ở vị trí 136 bị thay bằng Alanine"],0,"Giải thích: Bệnh HbE do đột biến điểm tại codon 26 của chuỗi beta-globin làm Acid glutamic bị thay thế bằng Lysine (Glu26Lys)."],["Bệnh Methemoglobin di truyền (HbM) thường do đột biến thay thế acid amin nào tại vị trí His F8 hoặc His E7 của chuỗi globin?",["Histidin bị thay thế bởi Tyrosine","Histidin bị thay thế bởi Alanine","Valine bị thay thế bởi Glutamate","Lysine bị thay thế bởi Proline"],0,"Giải thích: Đột biến HbM thường do Tyrosine thay thế Histidin F8 hoặc E7, tạo liên kết bền vững với Fe3+ ngăn enzyme reductase đưa Fe3+ trở lại Fe2+."],["Sự có mặt của sắc tố mật (Bilirubin trực tiếp) trong nước tiểu làm nước tiểu có màu sẫm như nước trà đậm hoặc màu nghệ là dấu hiệu gợi ý căn nguyên vàng da nào?",["Vàng da sau gan (tắc mật) hoặc Vàng da tại gan","Vàng da trước gan (tán huyết đơn thuần)","Vàng da do nhịn ăn","Thiếu hụt sắt mạn tính"],0,"Giải thích: Sắc tố mật trong nước tiểu chính là Bilirubin trực tiếp (tan trong nước). Chỉ khi có tắc mật hoặc tổn thương gan làm Bil trực tiếp tràn vào máu mới xuất hiện sắc tố mật trong nước tiểu."],["Trong bệnh lý tắc mật hoàn toàn (Vàng da sau gan), hiện tượng phân bạc màu như phân cò là do thiếu hụt sắc tố nào xuống ruột?",["Stercobilin (do Bilirubin trực tiếp không xuống được ruột để tạo Stercobilinogen)","Biliverdin","Hemoglobin","Urobilin"],0,"Giải thích: Tắc mật hoàn toàn ngăn cản Bilirubin trực tiếp xuống ruột, vi khuẩn ruột không có nguyên liệu tạo Stercobilinogen/Stercobilin nên phân mất màu vàng nâu tự nhiên và có màu bạc xám. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 26 BỘ 120 CÂU HỎI TRẮC NGHIỆM HÓA HỌC & CHUYỂN HÓA HEMOGLOBIN ÔN THI Y - DƯỢC - RHM"],["Khái niệm 'Vàng da nhân' (Kernicterus) ở trẻ sơ sinh là tình trạng cấp cứu nguy hiểm do chất nào ngấm vào các nhân xám trung ương của não?",["Bilirubin gián tiếp (tự do) nồng độ quá cao tự do vượt ngưỡng gắn của Albumin","Bilirubin trực tiếp","Biliverdin","Hemoglobin tự do"],0,"Giải thích: Bilirubin gián tiếp tan trong mỡ và không gắn Albumin dễ dàng vượt qua hàng rào máu-não ngấm vào các tế bào thần kinh gây độc và tổn thương não vĩnh viễn (Vàng da nhân)."],["Vai trò mấu chốt của enzyme Glucose-6-Phosphate Dehydrogenase (G6PD) đối với sự bền vững màng hồng cầu là gì?",["Tạo NADPH duy trì Glutathione ở dạng khử (GSH) bảo vệ hồng cầu khỏi các chất oxy hóa","Tổng hợp trực tiếp chuỗi globin","Gắn sắt vào vòng Hem","Phân hủy Bilirubin gián tiếp"],0,"Giải thích: G6PD trong con đường Pentose Phosphate tạo NADPH, NADPH là coenzyme bắt buộc để Glutathione reductase tái tạo GSH khử các chất oxy hóa bảo vệ màng hồng cầu."],["Người bị thiếu hụt enzyme G6PD khi sử dụng các thuốc có tính oxy hóa mạnh (như thuốc chống sốt rét Primaquin, Sulfonamide) hoặc ăn đậu Fava sẽ bị hiện tượng gì?",["Tán huyết cấp tính gây thiếu máu và vàng da trước gan","Tắc mật cấp tính","Tăng tổng hợp HbF","Hạ đường huyết"],0,"Giải thích: Thiếu G6PD làm hồng cầu không đủ NADPH chống lại stress oxy hóa từ thuốc/thực phẩm, dẫn đến vỡ hồng cầu hàng loạt gây cơn tán huyết cấp."],["Trên điện di Hemoglobin ở pH kiềm (8.6), thứ tự di chuyển của các dạng Hb từ cực âm (-) về cực dương (+) là:",["HbA2/C -> HbS/E -> HbF -> HbA1","HbA1 -> HbF -> HbS -> HbA2","HbF -> HbA1 -> HbA2 -> HbS","HbS -> HbA1 -> HbF -> HbA2"],0,"Giải thích: Ở pH kiềm 8.6, tốc độ di chuyển về cực dương phụ thuộc điện tích âm: HbA2/C di chuyển chậm nhất (gần cực âm), tiếp theo là HbS/E, HbF và HbA1 di chuyển nhanh nhất về cực dương."],["Trong lâm sàng, xét nghiệm định lượng Urobilinogen trong nước tiểu bằng que thử 10 thông số dựa trên phản ứng màu với thuốc thử nào?",["Thuốc thử Ehrlich (p-dimethylaminobenzaldehyde)","Thuốc thử Biuret","Thuốc thử Ninhydrin","Thuốc thử Benedict"],0,"Giải thích: Urobilinogen phản ứng với thuốc thử Ehrlich (p-dimethylaminobenzaldehyde) tạo phức chất màu hồng đỏ đặc trưng."],["Tại sao ở bệnh nhân bị xơ gan nặng hoặc suy gan cấp, nồng độ Urea máu có thể giảm nhưng nồng độ NH3 và Bilirubin gián tiếp trong máu lại tăng cao?",["Tế bào gan bị suy giảm chức năng tổng hợp Urea và chức năng liên hợp Bilirubin","Thận bị tăng đào thải Urea quá mức","Ruột ngừng hấp thu acid amin","Hồng cầu ngừng phá hủy"],0,"Giải thích: Gan suy nặng không chuyển được NH3 thành Urea (làm NH3 tăng, Urea giảm) và không liên hợp được Bilirubin tự do (làm Bil gián tiếp tăng)."],["Trong chẩn đoán mức độ nặng của thiếu máu tán huyết, chỉ số cận lâm sàng nào trong huyết thanh thường bị GIẢM mạnh do bị tiêu thụ hết để gắn với Hb tự do?",["Nồng độ Haptoglobin huyết thanh","Nồng độ Bilirubin gián tiếp","Nồng độ Sắt huyết thanh","Nồng độ Ferritin"],0,"Giải thích: Khi tán huyết xảy ra, Hb giải phóng vào máu gắn bù trừ hết với Haptoglobin. Phức hợp Hb-Haptoglobin bị dọn dẹp tại gan làm nồng độ Haptoglobin tự do giảm sâu hoặc bằng 0."],["Sự kết hợp giữa 2 chuỗi alpha và 2 chuỗi gamma tạo nên loại Hemoglobin nào và có ý nghĩa thích nghi sinh lý gì ở thai nhi?",["HbF (alpha2 gamma2), giúp thai nhi dễ dàng lấy O2 từ máu mẹ qua nhau thai nhờ ái lực O2 cao","HbA1, giúp thai nhi tự hô hấp","HbA2, giúp chống hạ đường huyết","HbS, giúp thai nhi chịu được thiếu máu"],0,"Giải thích: HbF (alpha2 gamma2) có ái lực O2 cao hơn HbA1 của mẹ, giúp thai nhi tranh chấp và nhận O2 hiệu quả từ tuần hoàn mẹ qua bánh nhau. Tài liệu ôn tập Sinh hóa học - Chuyên đề Hemoglobin Trang 27"]];
